const e=(s,c,d)=>({tipo:"opcion",enunciado:s,opciones:c,correcta:0,explicacion:d}),a=(s,c,d)=>({tipo:"vf",enunciado:s,correcta:c,explicacion:d}),r=(s,c,d)=>({tipo:"ordenar",enunciado:s,pasos:c,explicacion:d}),i=(s,c,d,t)=>({tipo:"completar",enunciado:s,frase:c,opciones:d,correcta:0,explicacion:t});function o(s){return{...s,preguntas:s.preguntas.map((c,d)=>({...c,id:`${s.id}-p${d+1}`}))}}const u="https://sjconsulta.csjn.gov.ar/sjconsulta/documentos",l=(s,c)=>({etiqueta:`Fallo completo · CSJN, Fallos ${c}`,url:`${u}/${s}`}),n={polak:l("verDocumentoSumario.html?idDocumentoSumario=7009","321:2826"),mattei:l("verDocumentoByIdLinksJSP.html?idDocumento=7834641","272:188"),mozzatti:l("verDocumentoSumario.html?idDocumentoSumario=16387","300:1102"),montenegro:l("verDocumentoSumario.html?idDocumentoSumario=23105","303:1938"),verbitsky:l("verDocumentoByIdLinksJSP.html?idDocumento=5824581","328:1146"),napoli:l("verDocumentoByIdLinksJSP.html?idDocumento=4627541","321:3630"),rayford:l("verDocumentoSumario.html?idDocumentoSumario=30882","308:733"),llerena:l("verDocumentoByIdLinksJSP.html?idDocumento=5841071","328:1491"),mostaccio:l("verDocumentoByIdLinksJSP.html?idDocumento=5534771","327:120"),acosta:l("verDocumentoByIdLinksJSP.html?idDocumento=6424841","331:858"),gongora:l("verDocumentoByIdLinksJSP.html?idDocumento=7008981","336:392"),casal:l("verDocumentoByIdLinksJSP.html?idDocumento=5921391","328:3399"),bulacio:{etiqueta:"Sentencia completa · Corte IDH, Serie C 100",url:"https://www.corteidh.or.cr/docs/casos/articulos/seriec_100_esp.pdf"},fernandezPrieto:{etiqueta:"Sentencia completa · Corte IDH, Serie C 411",url:"https://corteidh.or.cr/docs/casos/articulos/seriec_411_esp.pdf"},peiranoBasso:{etiqueta:"Informe completo · CIDH, Informe 86/09",url:"https://www.cidh.oas.org/annualrep/2009sp/uruguay12553.sp.htm"},scbaVerbitsky2022:{etiqueta:"Resolución completa · SCBA, P. 83.909 (Word)",url:"https://www-2020.scba.gov.ar/falloscompl/scba/inter/2022/05-03/p83909.doc"},scbaCarrascosa:{etiqueta:"Sentencia completa · SCBA, P. 125.776 (Word)",url:"https://www-2020.scba.gov.ar/falloscompl/scba/2016/06-01/p125776.doc"},scbaPitman:{etiqueta:"Sentencia completa · SCBA, P. 137.668",url:"https://www.scba.gov.ar/includes/descarga.asp?id=54082&n=Ver+sentencia+(causa+P137.668).pdf"},tcpAguero:{etiqueta:"Sentencia completa · TCP, Sala V, causa 133.216",url:"https://www.scba.gov.ar/includes/descarga.asp?id=55453&n=Ver+sentencia+(causa+N%C2%B0+133.216).pdf"},tcpGuerendiain:{etiqueta:"Sentencia completa · TCP, Sala IV, causa 76.889",url:"https://www.scba.gov.ar/includes/descarga.asp?id=35615&n=Ver+Sentencia+%2876889%29.pdf"}},p={id:"u1",numero:1,titulo:"Garantías del proceso",subtitulo:"Las reglas de juego que protegen a toda persona acusada",etapa:"Principios y garantías",color:"azul",icono:"🛡️",temas:[{articuloId:"cppba-1",relacionados:["cppba-3","cppba-22-bis"],falloClave:{tribunal:"Corte Suprema de Justicia de la Nación",caso:"«Polak, Federico Gabriel»",anio:"1998",resumen:"Un imputado había sido juzgado válidamente y, por un error que no le era atribuible, se anuló el juicio para hacerlo de nuevo. La Corte entendió que retrotraer el proceso a etapas ya cumplidas, cuando el imputado no causó el vicio, lo expone otra vez al riesgo de condena.",regla:"El non bis in ídem prohíbe no sólo una segunda pena, sino también un nuevo juicio y la renovación del riesgo de condena por el mismo hecho.",nota:"Síntesis didáctica (Fallos 321:2826, 15/10/1998).",enlaces:[n.polak],ambito:"nacional"},fallosRelacionados:[{tribunal:"Suprema Corte de Justicia de la Provincia de Buenos Aires",caso:"«Pitman y otros» (P. 137.668 y P. 137.671)",anio:"2024",resumen:"Un jurado de Mar del Plata declaró no culpables a tres acusados. Los particulares damnificados pidieron la nulidad del juicio y la Casación, por vía de queja, anuló el debate y el veredicto y ordenó un nuevo juicio con otro jurado. La SCBA revocó esa decisión y restableció el veredicto de no culpabilidad.",regla:"Anular un veredicto de no culpabilidad del jurado para hacer un nuevo juicio expone a los acusados a un nuevo riesgo de condena por el mismo hecho: lo prohíbe el non bis in ídem. La absolución derivada del veredicto del jurado es irrecurrible (art. 371 quater, ap. 7).",nota:"Síntesis de la sentencia de marzo de 2024 (registrada el 21/3/2024).",enlaces:[n.scbaPitman],ambito:"bonaerense"}],lecciones:[o({id:"u1-a1-l1",titulo:"Juez natural y juicio previo",minutos:4,intro:{titulo:"¿Quién puede juzgarte?",parrafos:["El artículo 1 del CPPBA es la puerta de entrada al código: reúne las garantías que la Constitución reconoce a cualquier persona acusada de un delito.","La primera es el juez natural: sólo pueden juzgarte los jueces designados de acuerdo con la Constitución de la Provincia y competentes según sus leyes. El art. 18 de la Constitución Nacional agrega que deben estar designados por ley ANTES del hecho: nadie puede armar un tribunal especial para un caso.","La segunda es el juicio previo: para que haya pena tiene que haber antes un juicio, fundado en una ley anterior al hecho y tramitado conforme al código. Desde la Ley 14.543, el art. 1 también remite al juicio por jurados en causas criminales (art. 22 bis: delitos con pena máxima de más de 15 años)."],enLaPractica:"Si una causa de Lomas de Zamora se asignara a un juzgado creado especialmente después del hecho para «ese» imputado, la defensa podría objetarlo por violar el juez natural."},foco:"Nadie podrá ser juzgado por otros jueces que los designados de acuerdo con la Constitución de la Provincia y competentes según sus leyes reglamentarias",preguntas:[e("¿Qué exige la garantía del juez natural según el art. 1 CPPBA?",["Jueces designados conforme a la Constitución provincial y competentes según sus leyes","Que intervenga el juez del lugar donde vive el imputado","Que la causa la resuelva el juez que la Suprema Corte designe para ese caso","Que el imputado pueda elegir entre un juez técnico y un jurado en cualquier delito"],"El art. 1 exige jueces designados de acuerdo con la Constitución de la Provincia y competentes según sus leyes; el art. 18 CN agrega que deben estar designados antes del hecho. La competencia territorial se fija por el lugar del hecho, no por el domicilio, y el jurado sólo rige en los delitos del art. 22 bis."),e("Tras un homicidio muy mediático, se crea por ley un tribunal especial para juzgar sólo ese caso. ¿Qué garantía del art. 1 se afecta?",["El juez natural","El non bis in ídem","El favor rei","La inviolabilidad de la defensa"],"Un tribunal armado después del hecho y «a medida» de una causa viola el juez natural. Las otras garantías existen, pero no son las que están en juego aquí."),i("Completá el artículo 1.","Nadie podrá ser penado sin ___ fundado en ley anterior al hecho del proceso.",["juicio previo","acusación fiscal","sentencia firme","investigación preparatoria"],"Es la garantía de juicio previo: primero el juicio, después (si corresponde) la pena. La «sentencia firme» aparece en otra parte del artículo, en el estado de inocencia."),e("¿En qué causas interviene el Tribunal de jurados (art. 22 bis CPPBA)?",["En delitos cuya pena máxima en abstracto exceda de quince (15) años","En delitos cuya pena máxima supere los ocho (8) años","En todos los delitos de competencia del Tribunal en lo Criminal","Sólo en homicidios dolosos consumados"],"El art. 22 bis atribuye al jurado los delitos con pena máxima en abstracto de más de 15 años (o un concurso en que alguno lo supere). Hasta 15 años, el Tribunal en lo Criminal es unipersonal salvo excepciones (art. 22)."),a("El imputado puede renunciar al juicio por jurados incluso después de que quedó firme la requisitoria de elevación a juicio.",!1,"Falso. La renuncia debe hacerse en el plazo del art. 336 y ratificarse ante el juez; una vez firme la requisitoria «no podrá renunciarse al juicio por jurados, bajo pena de nulidad» (art. 22 bis).")]}),o({id:"u1-a1-l2",titulo:"Inocencia y non bis in ídem",minutos:4,intro:{titulo:"Inocente hasta la sentencia firme",parrafos:["Mientras no haya una sentencia firme (es decir, que ya no puede recurrirse), el imputado es inocente. Por eso estar preso durante el proceso es la excepción y nunca puede funcionar como un castigo adelantado.","El non bis in ídem impide perseguir a alguien dos veces por el mismo hecho. No importa si la primera vez terminó con condena, absolución o sobreseimiento firme: el Estado tuvo su oportunidad.","En el juicio por jurados la garantía se ve con claridad: la sentencia absolutoria derivada de un veredicto de no culpabilidad es irrecurrible (art. 371 quater, ap. 7)."],enLaPractica:"Si un joven fue sobreseído definitivamente por un hurto y meses después otra UFI lo cita por el mismo episodio, la defensa plantea la excepción de falta de acción (art. 328 inc. 2) invocando el non bis in ídem."},foco:"ni considerado culpable mientras una sentencia firme no lo declare tal; ni perseguido penalmente más de una vez por el mismo hecho",preguntas:[e("¿Hasta cuándo rige el estado de inocencia?",["Hasta que una sentencia firme declare la culpabilidad","Hasta el veredicto de culpabilidad del jurado o del tribunal","Hasta que el Tribunal de Casación confirma la condena","Hasta que se dicta la prisión preventiva"],"La sentencia debe estar firme. Un veredicto o una condena confirmada en Casación todavía pueden recurrirse (por ejemplo, ante la SCBA o la CSJN): mientras tanto, la persona sigue siendo inocente."),a("El non bis in ídem sólo impide una segunda condena; un segundo juicio por el mismo hecho estaría permitido.",!1,"Falso. La garantía prohíbe la doble PERSECUCIÓN: ya el riesgo de un nuevo proceso por el mismo hecho está vedado (CSJN, «Polak»)."),e("Martín fue sobreseído con resolución firme por un hurto. Otra fiscalía lo cita por el mismo hecho. ¿Qué corresponde plantear?",["La excepción de falta de acción por cosa juzgada (non bis in ídem)","La nulidad de la citación porque no se notificó al defensor","La suspensión del juicio a prueba","La acumulación de ambas causas por conexión"],"El sobreseimiento firme cierra el caso. La vía es la excepción de falta de acción (art. 328 inc. 2: la acción «no pudiera ser proseguida»). Las otras opciones aceptan que la persecución siga."),e("Un jurado declaró «no culpable» a Lucas. El Fiscal quiere recurrir para que haya un nuevo juicio. ¿Qué establece el CPPBA?",["La sentencia absolutoria derivada del veredicto de no culpabilidad es irrecurrible","Puede recurrir en casación si el veredicto se apartó de la prueba","Puede recurrir si el veredicto no fue unánime","Puede pedir un nuevo jurado si el particular damnificado lo solicita"],"Art. 371 quater, ap. 7: «La sentencia absolutoria derivada del veredicto de no culpabilidad del jurado es irrecurrible». El apartamiento de la prueba (art. 448 bis, inc. d) es motivo de recurso sólo contra la condena. La SCBA lo aplicó en «Pitman» (2024)."),i("Completá.","Nadie podrá ser perseguido penalmente ___ por el mismo hecho.",["más de una vez","sin acusación fiscal","sin sentencia firme","fuera de su departamento judicial"],"Es la fórmula clásica del non bis in ídem.")]}),o({id:"u1-a1-l3",titulo:"Defensa inviolable y favor rei",minutos:4,intro:{titulo:"La duda siempre favorece al imputado",parrafos:["La defensa en juicio es inviolable: el imputado tiene derecho a ser oído, a tener abogado, a conocer la acusación y a ofrecer prueba.","El favor rei manda que, ante la duda, se esté a lo más favorable al imputado. En la sentencia se traduce en el in dubio pro reo: si el tribunal no tiene certeza, absuelve. Y el art. 3 completa la idea: las normas que restringen derechos se interpretan restrictivamente.","Dos reglas más del art. 1: si se viola una garantía pensada para proteger al imputado, ese error no puede usarse en su contra; y para imponer una medida de seguridad a un inimputable hay que respetar las reglas del juicio."],enLaPractica:"Si el único testigo del robo duda en el juicio («creo que era él, pero estaba oscuro»), el Tribunal en lo Criminal no puede condenar: la duda razonable obliga a absolver."},foco:"En caso de duda deberá estarse siempre a lo que sea más favorable al imputado.",preguntas:[e("Al cerrar el debate, los jueces creen probable que Ana sea la autora, pero no están seguros. ¿Qué corresponde?",["Absolver: la duda favorece a la imputada","Condenar al mínimo de la escala penal","Ordenar de oficio una instrucción suplementaria","Condenar si el particular damnificado mantiene la acusación"],"La condena exige certeza: la probabilidad no alcanza. Es el in dubio pro reo, derivado del favor rei del art. 1."),e("¿Qué significa «favor rei»?",["Ante la duda, estar a lo más favorable al imputado","Ante la duda, el juez debe producir nuevas pruebas de oficio","Ante la duda sobre la ley aplicable, rige la vigente al dictar el fallo","Ante la duda, se sigue el dictamen del Fiscal por su criterio objetivo"],"Es un principio de interpretación y de valoración: la duda juega a favor del imputado."),e("Se omitió notificar al imputado una audiencia, en violación de una regla de garantía. ¿Puede el Fiscal invocar esa omisión para perjudicarlo?",["No: una garantía establecida en su beneficio no puede hacerse valer en su perjuicio","Sí, si la defensa no planteó la nulidad a tiempo","Sí, porque la omisión no es imputable al Fiscal","Sólo si el acto puede renovarse sin afectar la defensa"],"El art. 1 lo dice expresamente: «La inobservancia de una regla de garantía establecida en beneficio del imputado no se podrá hacer valer en su perjuicio»."),a("Para imponer una medida de seguridad a una persona inimputable (art. 34 inc. 1 CP) no hace falta respetar las reglas del juicio.",!1,"Falso. El último párrafo del art. 1 exige la previa observancia de las normas del juicio (Libro III) para imponer medidas de seguridad."),e("Una norma que limita la libertad durante el proceso admite dos lecturas. ¿Cómo debe interpretarse (art. 3)?",["Restrictivamente","Extensivamente, para proteger a la víctima","Por analogía con el código federal","Según el criterio del Fiscal"],"El art. 3 manda interpretar restrictivamente toda disposición que coarte la libertad, restrinja derechos o establezca sanciones procesales o exclusiones probatorias.")]})]},{articuloId:"cppba-2",falloClave:{tribunal:"Corte Suprema de Justicia de la Nación",caso:"«Mattei» (1968) y «Mozzatti» (1978)",resumen:"En «Mattei» la Corte afirmó que el imputado tiene derecho a obtener un pronunciamiento que, definiendo su situación, ponga fin del modo más rápido posible a la incertidumbre que implica el proceso. En «Mozzatti», frente a un proceso que llevaba alrededor de 25 años, declaró extinguida la acción porque la duración había desnaturalizado la garantía de defensa.",regla:"La duración irrazonable del proceso viola la defensa en juicio y puede llevar a ponerle fin. Se evalúa la complejidad del caso, la conducta del imputado y la de las autoridades.",nota:"Síntesis didáctica (Fallos 272:188 y 300:1102).",enlaces:[n.mattei,n.mozzatti],ambito:"nacional"},lecciones:[o({id:"u1-a2-l1",titulo:"Plazo razonable",minutos:4,intro:{titulo:"Un proceso no puede durar para siempre",parrafos:["Estar imputado genera angustia, gastos y estigma. Por eso el art. 2 reconoce el derecho a ser juzgado en un tiempo razonable y sin dilaciones indebidas.","Para el código, el retardo en dictar sentencia y las dilaciones indebidas, cuando son reiteradas, no son un detalle: constituyen falta grave.","¿Qué es «razonable»? No hay un número mágico: se mira la complejidad del caso, lo que hizo el imputado y lo que hicieron (o no) los fiscales y jueces. Ojo: el tope de 2 años del art. 141 es otra cosa y rige sólo con imputado detenido."],enLaPractica:"En una causa simple por lesiones leves que quedó paralizada años en un despacho sin que nadie la impulsara, la defensa puede invocar la violación del plazo razonable."},foco:"Toda persona sometida a proceso tendrá derecho a ser juzgada en un tiempo razonable y sin dilaciones indebidas.",preguntas:[e("¿Qué derecho reconoce el art. 2 del CPPBA?",["A ser juzgado en un tiempo razonable y sin dilaciones indebidas","A ser juzgado dentro de los dos años, aunque esté en libertad","A que la IPP no supere los cuatro meses en ningún caso","A que el juicio se fije dentro de los treinta días de la elevación"],"El art. 2 consagra el plazo razonable (art. 8.1 CADH), un estándar flexible. Los 2 años son el tope del art. 141 con detenido, y los 4 meses, el plazo prorrogable de la IPP (art. 282)."),a("El retardo en dictar sentencia y las dilaciones indebidas, cuando son reiteradas, constituyen falta grave.",!0,"Verdadero: el art. 2 las califica expresamente como falta grave."),e("¿Qué pautas se usan para medir si un plazo es razonable?",["Complejidad del caso, actividad del imputado y conducta de las autoridades","Gravedad del delito, pena en expectativa y alarma social","Cantidad de imputados, de testigos y de fojas","Sólo el tiempo transcurrido desde el hecho"],"Son los criterios de la Corte Interamericana y de la CSJN. La gravedad del delito no justifica por sí sola un proceso eterno."),e("Una causa por lesiones leves, con el imputado en libertad, lleva siete años sin actividad del Fiscal ni del juzgado. ¿Qué planteo es más sólido?",["La violación del plazo razonable (art. 2 CPPBA y 8.1 CADH)","El vencimiento del plazo fatal de dos años del art. 141","La nulidad de la IPP por exceder los cuatro meses del art. 282","La caducidad de la instancia por inactividad de la víctima"],"El art. 141 exige que el imputado esté privado de libertad, y el plazo del art. 282 no genera nulidad automática. Lo que corresponde es invocar el plazo razonable («Mattei», «Mozzatti»).")]})]},{articuloId:"cppba-141",relacionados:["cppba-2","cppba-282"],lecciones:[o({id:"u1-a2-l2",titulo:"Plazos fatales con detenido (art. 141)",minutos:4,intro:{titulo:"Cuando hay alguien preso, el reloj corre más fuerte",parrafos:["Si el imputado está privado de su libertad, el código endurece los tiempos: los términos para completar la IPP y la duración total del proceso pasan a ser plazos fatales.","Según el art. 141, en ese caso el proceso no puede durar más de dos años. En un caso de suma complejidad se está al plazo razonable del art. 2, sujeto a la apreciación judicial.","Dos detalles prácticos: si se acumulan causas por conexión, los términos corren por separado desde la acumulación; y no se computa el tiempo de prueba fuera de la circunscripción, de los incidentes ni de los recursos."],enLaPractica:"Ante una prisión preventiva que se estira sin juicio a la vista, la defensa controla los plazos del art. 141 y del art. 282 (duración de la IPP) para pedir el cese de la detención."},foco:"el cual no podrá durar más de dos (2) años",preguntas:[e("Según el art. 141, ¿cuándo se vuelven fatales los plazos de la IPP y del proceso?",["Cuando el imputado está privado de su libertad","Cuando el delito tiene una pena máxima superior a ocho años","Cuando el Fiscal declara la causa compleja","En toda causa, esté o no detenido el imputado"],"La fatalidad de los plazos se vincula con la detención: la libertad no puede quedar restringida indefinidamente."),i("Completá la regla general del art. 141.","Con imputado privado de libertad, el proceso no podrá durar más de ___.",["dos (2) años","cuatro (4) meses","seis (6) meses","ocho (8) meses"],"Dos años es el tope general. Cuatro meses es el plazo de la IPP (art. 282), prorrogable hasta seis en casos excepcionales; ocho meses es el plazo para pedir una nueva audiencia del art. 168 bis."),a("En un caso de suma complejidad puede aplicarse, en lugar del tope fijo, el plazo razonable del art. 2.",!0,"Verdadero: «En un caso de suma complejidad, deberá estarse al plazo razonable del artículo 2º», sujeto a la apreciación judicial."),e("¿Qué tiempo NO se computa para los términos fatales?",["El de los recursos","El de la investigación penal preparatoria","El de la prisión preventiva","El del juicio oral"],"El art. 141 excluye el tiempo de diligenciamiento de pruebas fuera de la circunscripción judicial, el de los incidentes y el de los recursos."),e("Se acumulan dos causas por conexión. ¿Cómo corren los términos fatales?",["Separadamente para cada causa, desde la acumulación","Desde la primera detención, sumando ambas causas","Se reinician desde cero para las dos causas","Quedan suspendidos hasta que se unifique la pena"],"Art. 141: «los términos fatales previstos correrán separadamente para cada causa a partir de la respectiva acumulación».")]})]},{articuloId:"cp-2",relacionados:["cp-3"],lecciones:[o({id:"u1-cp2-l1",titulo:"Ley penal más benigna (CP)",minutos:4,intro:{titulo:"Si la ley cambia, se aplica la más favorable",parrafos:["El Código Penal se conecta con las garantías procesales a través del art. 2: si entre el hecho y la sentencia (o durante la condena) cambia la ley, se aplica siempre la más benigna.","La nueva ley más favorable opera «de pleno derecho»: no hace falta que el condenado lo pida para que rija, aunque en la práctica la defensa lo plantea.","Y el art. 3 CP agrega que para computar la prisión preventiva se aplica, por separado, la ley más favorable al procesado."],enLaPractica:"Si una reforma reduce la pena de un delito mientras el juicio está en trámite en un Tribunal en lo Criminal bonaerense, el tribunal debe aplicar la escala nueva, más favorable."},foco:"se aplicará siempre la más benigna",preguntas:[e("El hecho se cometió con una ley; al momento del fallo rige otra más benigna. ¿Cuál se aplica?",["La más benigna","La vigente al momento del hecho","La vigente al momento del fallo, aunque fuera más gravosa","La que resulte de promediar ambas escalas"],"El art. 2 CP manda aplicar siempre la más benigna, sea la del hecho, la intermedia o la del fallo. No existe el «promedio» de escalas."),a("Si la ley más benigna se dicta durante el cumplimiento de la condena, ya no se puede aplicar.",!1,"Falso. El segundo párrafo del art. 2 CP dispone que la pena se limita a la establecida por la nueva ley."),i("Completá el art. 2 CP.","En todos los casos del presente artículo, los efectos de la nueva ley se operarán ___.",["de pleno derecho","a pedido de parte","por resolución de la Cámara","desde que la sentencia quede firme"],"«De pleno derecho»: la ley más benigna rige automáticamente."),e("¿Qué regla trae el art. 3 CP para la prisión preventiva?",["Para su cómputo se aplica separadamente la ley más favorable al procesado","Se computa según la ley vigente al momento del hecho","Se computa según la ley vigente al dictarse la sentencia","Se computa según la ley vigente al momento de la detención"],"El art. 3 CP aplica el principio de benignidad también al cómputo de la preventiva, en forma separada.")]})]}],caso:{id:"caso-u1",titulo:"El hurto que volvió",rol:"Defensa oficial",sede:"Juzgado de Garantías · Departamento Judicial La Matanza (caso ficticio)",hechos:["Martín (22) fue sobreseído en 2024, con resolución firme, en una causa por el hurto de una bicicleta (art. 162 CP): se probó que la bicicleta era suya.","Un año después, el denunciante insiste ante otra UFI con una nueva denuncia por el mismo episodio. La fiscalía cita a Martín a declarar.","Te toca asumir su defensa."],etapas:[{id:"e1",momento:"Primera entrevista con Martín",situacion:"Martín te muestra la resolución de sobreseimiento firme y la nueva citación. El hecho, la fecha y la bicicleta son los mismos.",pregunta:"¿Qué estrategia elegís?",opciones:[{texto:"Oponer la excepción de falta de acción invocando la cosa juzgada y el non bis in ídem (arts. 1 y 328 inc. 2 CPPBA).",puntaje:2,devolucion:"¡Exacto! Hay identidad de persona, de hecho y de causa de persecución. El sobreseimiento firme impide un nuevo proceso: la garantía protege contra el riesgo mismo de volver a ser juzgado."},{texto:"Que declare y vuelva a explicar que la bicicleta es suya.",puntaje:0,devolucion:"Declarar no es necesario y además legitima una persecución prohibida. El Estado ya agotó su oportunidad con el sobreseimiento firme."},{texto:"Esperar al juicio y plantear el non bis in ídem en el alegato final.",puntaje:1,devolucion:"Llegarías tarde: el non bis in ídem prohíbe la doble persecución, no sólo la doble condena. Hay que plantearlo de inmediato para cortar el nuevo proceso."}],normas:["Art. 1 CPPBA","Arts. 328 y 329 CPPBA (excepciones)"]},{id:"e2",momento:"Otra causa de Martín",situacion:"Martín tiene además un proceso en trámite por un delito cuya escala penal fue reducida por una ley sancionada después del hecho, antes de la sentencia.",pregunta:"¿Qué ley debe aplicar el tribunal?",opciones:[{texto:"La ley nueva, por ser más benigna (art. 2 CP).",puntaje:2,devolucion:"Correcto. Se aplica siempre la más benigna, y sus efectos operan de pleno derecho."},{texto:"La vigente al momento del hecho, porque «la ley no es retroactiva».",puntaje:0,devolucion:"La irretroactividad protege contra leyes más gravosas. La ley penal más benigna sí es retroactiva."},{texto:"La que resulte de promediar ambas escalas.",puntaje:0,devolucion:"No existe ese promedio: se aplica íntegramente la ley más benigna."}],normas:["Art. 2 CP","Art. 9 CADH"]},{id:"e3",momento:"Juicio por la segunda causa",situacion:"En el debate, la única testigo dice: «Me parece que era él, pero estaba oscuro y lo vi de espaldas». No hay otra prueba de autoría.",pregunta:"¿Qué pedís en tu alegato?",opciones:[{texto:"La absolución por aplicación del in dubio pro reo (favor rei, art. 1 CPPBA).",puntaje:2,devolucion:"Muy bien. Sin certeza sobre la autoría, la duda debe resolverse a favor del imputado."},{texto:"Una pena mínima, porque la testigo «algo» lo reconoció.",puntaje:0,devolucion:"Pedir una pena mínima es conceder la autoría. La condena exige certeza; una identificación dubitativa no alcanza."},{texto:"Que se suspenda el juicio hasta que aparezca más prueba.",puntaje:1,devolucion:"El proceso no puede quedar abierto indefinidamente a la espera de prueba de cargo (plazo razonable). La respuesta correcta es la absolución."}],normas:["Art. 1 CPPBA","Art. 2 CPPBA"]}],cierre:{titulo:"Garantías en acción",texto:"Usaste tres herramientas del art. 1 CPPBA y del art. 2 CP: el non bis in ídem para frenar una persecución repetida, la ley penal más benigna y el in dubio pro reo. Son argumentos que aparecen todas las semanas en los juzgados bonaerenses."}}},m={id:"u2",numero:2,titulo:"Fiscal, imputado y declaración",subtitulo:"Quién acusa, quién se defiende y cómo se declara",etapa:"Sujetos del proceso",color:"naranja",icono:"⚖️",temas:[{articuloId:"cppba-56",relacionados:["cp-71","cp-72"],lecciones:[o({id:"u2-a56-l1",titulo:"El Fiscal: acusa e investiga",minutos:3,intro:{titulo:"El motor de la acción penal",parrafos:["En la Provincia de Buenos Aires rige un sistema acusatorio: quien investiga y acusa (el Ministerio Público Fiscal) no es quien decide (el juez).","El art. 56 le asigna al Fiscal tres funciones: promover y ejercer la acción penal pública, dirigir a la Policía en función judicial y practicar la Investigación Penal Preparatoria (IPP).","Los fiscales trabajan en Unidades Funcionales de Instrucción (UFI) de cada departamento judicial."],enLaPractica:"Cuando la policía de una comisaría de Quilmes detiene a alguien, inmediatamente da aviso a la UFI de turno: desde ese momento el Fiscal dirige la investigación."},foco:"promoverá y ejercerá la acción penal de carácter público",preguntas:[e("¿Quién practica la Investigación Penal Preparatoria en el CPPBA?",["El Ministerio Público Fiscal","El Juez de Garantías","La Policía en función judicial, con control del juez","El Tribunal en lo Criminal"],"El Fiscal investiga; el Juez de Garantías controla y la Policía actúa bajo la dirección del Fiscal. Es la base del modelo acusatorio bonaerense."),r("Ordená las funciones del Fiscal según aparecen en el art. 56:",["Promover y ejercer la acción penal pública","Dirigir a la Policía en función judicial","Practicar la Investigación Penal Preparatoria"],"Ese es el orden del primer párrafo del art. 56."),a("En el CPPBA el mismo juez que investiga es el que después dicta la sentencia.",!1,"Falso. Separar investigación y juzgamiento protege la imparcialidad: investiga el Fiscal, controla el Juez de Garantías y juzga otro tribunal."),e("¿Qué dirige el Fiscal además de la IPP?",["A la Policía en función judicial","A la Policía de seguridad en tareas de prevención","Al Juez de Garantías durante la IPP","Al Defensor Oficial en la etapa preparatoria"],"El art. 56 le asigna la dirección de la Policía «en función judicial», es decir, cuando investiga delitos; no la prevención general ni, menos aún, a jueces o defensores.")]}),o({id:"u2-a56-l2",titulo:"Objetividad del Fiscal",minutos:4,intro:{titulo:"Acusar no es perseguir a cualquier costo",parrafos:["El Fiscal debe actuar con criterio objetivo: buscar la verdad, también lo que favorece al imputado.","Por eso el art. 56 le exige formular sus requerimientos conforme a ese criterio «aún a favor del imputado» (por ejemplo, pidiendo el sobreseimiento o la absolución), y fundarlos de manera que se basten a sí mismos.","Además puede aplicar criterios de oportunidad en cualquier etapa, en especial los que favorecen la reparación de la víctima. El art. 56 bis regula el archivo en tres supuestos: insignificancia (con pena máxima de hasta 6 años), daño sufrido por el propio imputado («pena natural») y pena irrelevante frente a otros delitos."],enLaPractica:"Si en el debate la prueba demuestra que el imputado actuó en legítima defensa, el Fiscal objetivo debe pedir la absolución aunque él mismo haya acusado."},foco:"adecuará sus actos a un criterio objetivo",preguntas:[a("El Fiscal debe pedir la absolución si la prueba favorece al imputado.",!0,"Verdadero. El art. 56 le exige formular sus requerimientos conforme al criterio objetivo, «aún a favor del imputado»."),i("Completá el art. 56.","Adecuará sus actos a un criterio ___.",["objetivo","de oportunidad","acusatorio","de legalidad"],"Objetividad: el Fiscal representa el interés de la sociedad en que se aplique correctamente la ley, no en condenar."),e("¿Cómo deben ser los requerimientos del Fiscal?",["Motivados, de manera que se basten a sí mismos","Escritos en todos los casos, incluso durante el debate","Breves, con remisión a las constancias de la causa","Fundados sólo cuando la defensa lo pida"],"El art. 56 le exige formular motivadamente sus requerimientos y conclusiones, «de manera que se basten a sí mismos»; en los debates procede oralmente."),e("Un imputado sin antecedentes sustrajo mercadería de valor ínfimo de un supermercado (hurto, pena máxima de 2 años) y ofrece reparar. ¿Qué herramienta tiene el Fiscal?",["Archivar por insignificancia (art. 56 bis inc. 1)","Sobreseer por prescripción de la acción","Desistir porque el hurto es de acción privada","Ofrecer un juicio abreviado sin pena"],"El art. 56 bis inc. 1 permite archivar cuando la afectación del bien jurídico es insignificante y la pena máxima no supera 6 años; se considera especialmente la reparación. El archivo debe notificarse a la víctima, que puede pedir su revisión al Fiscal General.")]})]},{articuloId:"cp-71",relacionados:["cp-72","cp-59"],lecciones:[o({id:"u2-cp71-l1",titulo:"Acciones públicas, de instancia y privadas",minutos:4,intro:{titulo:"¿Quién puede poner en marcha el proceso?",parrafos:["El Código Penal (arts. 71 a 73) clasifica las acciones. La regla es la acción pública: el Fiscal actúa de oficio, «sin perjuicio de las reglas de disponibilidad de la acción penal previstas en la legislación procesal» (Ley 27.147).","Algunas son dependientes de instancia privada (art. 72): abusos sexuales de los arts. 119, 120 y 130 sin muerte ni lesiones gravísimas, lesiones leves e impedimento de contacto. Hace falta la denuncia de la víctima para empezar; luego sigue de oficio.","Hay excepciones: se procede de oficio si la víctima del abuso es menor de 18 años o incapaz, y en las lesiones leves cuando median razones de seguridad o interés público. Las acciones privadas (por ejemplo, calumnias e injurias) se impulsan por querella."],enLaPractica:"En una pelea con lesiones leves (art. 89 CP), la UFI no puede avanzar si la víctima no insta la acción, salvo razones de seguridad o interés público."},preguntas:[e("Según el art. 71 CP, ¿cuál es la regla?",["Se inician de oficio, salvo las de instancia privada y las privadas","Todas requieren la denuncia de la víctima","El Fiscal elige libremente cuáles inicia","Sólo se inician de oficio los delitos con pena mayor a 3 años"],"La regla es la acción de oficio; las excepciones son las de instancia privada y las privadas. Las «reglas de disponibilidad» que menciona el art. 71 (criterios de oportunidad) las fija la ley procesal, no el Fiscal a su arbitrio."),e("¿Qué tipo de acción nace de unas lesiones leves dolosas?",["Dependiente de instancia privada","Privada","Pública de oficio","Pública, salvo que la víctima se oponga"],"El art. 72 inc. 2 CP incluye las lesiones leves, dolosas o culposas."),a("En los delitos dependientes de instancia privada se puede proceder de oficio cuando median razones de seguridad o interés público en las lesiones leves.",!0,"Verdadero: el propio art. 72 CP prevé esa excepción para el inciso de lesiones leves."),a("En un abuso sexual del art. 119 CP sin muerte ni lesiones gravísimas, si la víctima tiene 15 años se procede de oficio.",!0,"Verdadero. El art. 72 (Ley 27.455) dispone que en los casos del inciso 1 se procede de oficio cuando la víctima es menor de 18 años o fue declarada incapaz."),e("Desde la Ley 27.147, ¿cuál de estas es una causal de extinción de la acción penal (art. 59 CP)?",["La conciliación o reparación integral, según las leyes procesales","El desistimiento de la denuncia en un delito de acción pública","El perdón del Fiscal en delitos con pena menor a 3 años","El pago voluntario de una multa en cualquier delito"],"El art. 59 incorporó el criterio de oportunidad, la conciliación o reparación integral y el cumplimiento de la suspensión del juicio a prueba, siempre conforme a las leyes procesales."),i("Completá.","En los delitos de acción privada, el proceso se impulsa mediante ___.",["querella","instancia privada","requisitoria fiscal","denuncia ante la UFI"],"Las acciones privadas se ejercen por querella del agraviado (art. 8 y arts. 381 y ss. CPPBA).")]})]},{articuloId:"cppba-60",falloClave:{tribunal:"Corte Interamericana de Derechos Humanos",caso:"«Bulacio vs. Argentina»",anio:"2003",resumen:"Walter Bulacio, de 17 años, murió tras ser detenido en una razzia policial en 1991 sin que se avisara al juez ni a su familia. La Corte IDH condenó a la Argentina y remarcó los deberes del Estado frente a toda persona detenida.",regla:"Toda persona detenida tiene derecho a ser informada de las razones de su detención, a que se notifique sin demora a un juez y a sus familiares, y a contar con asistencia letrada desde el primer momento.",nota:"Síntesis didáctica (sentencia del 18/9/2003, Serie C 100).",enlaces:[n.bulacio],ambito:"interamericano"},lecciones:[o({id:"u2-a60-l1",titulo:"¿Quién es imputado?",minutos:3,intro:{titulo:"Los derechos llegan antes que la indagatoria",parrafos:["Para el CPPBA es imputado toda persona a la que, en cualquier acto o procedimiento, se la indique o detenga como autora o partícipe de un delito.","La clave: los derechos se pueden ejercer desde el primer momento de la persecución, aunque todavía nadie le haya tomado declaración ni haya una resolución formal."],enLaPractica:"Un patrullero demora a un joven señalado por un vecino como el autor de un robo: ya es imputado, y ya puede exigir saber de qué se lo acusa y llamar a un abogado."},foco:"desde el primer momento de la persecución penal dirigida en su contra",preguntas:[a("Una persona recién adquiere la calidad de imputado cuando el juez lo declara formalmente.",!1,"Falso. Basta con que se lo indique o detenga como autor o partícipe en cualquier acto o procedimiento."),e("¿Desde cuándo puede el imputado ejercer sus derechos?",["Desde el primer momento de la persecución penal en su contra","Desde que se le recibe declaración (art. 308)","Desde que el juez convierte la aprehensión en detención","Desde la requisitoria de citación a juicio"],"Es una regla amplia de protección: la defensa no espera a los actos formales."),i("Completá.","Se considerará imputado a toda persona que en cualquier acto o procedimiento se lo indique o ___ como autor o partícipe de la comisión de un delito.",["detenga","cite como testigo","notifique","identifique"],"Indicado o detenido: cualquiera de las dos situaciones activa sus derechos.")]}),o({id:"u2-a60-l2",titulo:"Garantías mínimas del imputado",minutos:4,intro:{titulo:"El kit básico de derechos",parrafos:["Desde la detención (o desde la primera diligencia, si el delito no admite detención), la autoridad debe informarle sus garantías mínimas: saber sin demora, en un idioma que comprenda y en detalle, de qué se lo acusa; comunicarse libremente con un abogado de su elección o con el Defensor Oficial (y, si es extranjero, con el Cónsul de su país); que no está obligado a declarar contra sí mismo ni a confesarse culpable; y sus derechos frente al responsable civil y la aseguradora, si los hubiera.","Si está detenido, puede presentar sus pedidos ante quien lo custodia, que debe comunicarlos de inmediato al órgano que interviene."],enLaPractica:"Si el imputado sólo habla guaraní, la declaración ante la UFI debe hacerse con intérprete. Sin él, el acto puede ser nulo."},preguntas:[e("¿Cuál de estos NO es un derecho del imputado?",["Declarar bajo juramento para que su versión tenga más valor","Ser informado de la imputación en un idioma que comprenda","Comunicarse con el Cónsul de su país, si es extranjero","Abstenerse de declarar"],"El imputado nunca declara bajo juramento: hacerlo violaría la garantía contra la autoincriminación (art. 18 CN)."),a("Si el imputado elige callar, el tribunal puede tomar ese silencio como indicio de culpabilidad.",!1,"Falso. El art. 60 le garantiza que no está obligado a declarar contra sí mismo: su silencio no puede usarse como indicio de culpabilidad."),e("Una persona no puede pagar un abogado. ¿Qué pasa?",["Lo asiste el Defensor Oficial","Puede declarar sin abogado si lo consiente por escrito","Se suspende la investigación hasta que consiga abogado","Lo asiste un abogado elegido por el Fiscal"],"El art. 60 le asegura el derecho a ser asistido y comunicarse con el Defensor Oficial si no tiene un abogado de confianza. Nunca declara sin asistencia letrada."),i("Completá.","El imputado será informado ___, en un idioma que comprenda y en forma detallada, de la imputación.",["sin demora","antes de la declaración","al elevarse la causa a juicio","dentro de las 48 horas"],"La información debe ser inmediata, comprensible y detallada."),e("Detienen en Avellaneda a un ciudadano uruguayo. Además de las garantías comunes, ¿qué debe informársele?",["Su derecho a comunicarse con el Cónsul de su país","Que deberá declarar en castellano, sin intérprete","Que no puede designar un abogado particular","Que será expulsado si se lo condena"],"El art. 60 incluye el derecho a comunicarse con el Cónsul; el art. 308 exige notificarle sin dilación su derecho a la asistencia consular, bajo sanción de nulidad (Convención de Viena sobre Relaciones Consulares).")]})]},{articuloId:"cppba-308",falloClave:{tribunal:"Corte Suprema de Justicia de la Nación",caso:"«Montenegro, Luciano Bernardino»",anio:"1981",resumen:"La condena se basaba en una confesión obtenida mediante apremios ilegales por la policía, que llevó a encontrar los objetos robados. La Corte dejó sin efecto la sentencia.",regla:"Una confesión obtenida bajo tormentos o apremios es inválida y no puede usarse como prueba: sería convertir al Estado en beneficiario de un hecho ilícito.",nota:"Síntesis didáctica (Fallos 303:1938).",enlaces:[n.montenegro],ambito:"nacional"},lecciones:[o({id:"u2-a308-l1",titulo:"Cuándo y en qué plazo se declara",minutos:3,intro:{titulo:"La declaración del imputado",parrafos:["Cuando existen elementos suficientes o indicios vehementes de un delito y motivo bastante para sospechar que una persona participó, el Fiscal debe recibirle declaración, previa notificación al defensor.","Si está aprehendida o detenida, la regla es la inmediatez: a más tardar dentro de las 24 horas desde que se produjo la restricción de la libertad, prorrogables por otro tanto si el Fiscal no pudo recibirla o si el imputado lo pide para proponer defensor.","En el sistema bonaerense la declaración la recibe el Fiscal; si el imputado lo pide motivadamente, puede declarar ante el Juez de Garantías."],enLaPractica:"Un aprehendido en flagrancia un viernes a la noche debe ser llevado ante la UFI para declarar dentro del plazo legal, aunque sea fin de semana: el turno no se interrumpe."},foco:"dentro de las veinticuatro (24) horas",preguntas:[e("¿Quién recibe la declaración del imputado en el CPPBA?",["El Agente Fiscal","El Juez de Garantías","El oficial que lo aprehendió","El Defensor Oficial"],"El art. 308 pone ese acto en cabeza del Fiscal, coherente con su rol de director de la IPP (salvo que el imputado pida motivadamente declarar ante el Juez de Garantías)."),i("Completá el plazo para el detenido.","Cuando el imputado se encuentre aprehendido o detenido, el acto deberá cumplirse inmediatamente o a más tardar dentro de las ___ desde el momento en que se produjo la restricción de la libertad.",["veinticuatro (24) horas","cuarenta y ocho (48) horas","setenta y dos (72) horas","doce (12) horas"],"La regla es 24 horas desde la restricción de la libertad, prorrogables por otro tanto en los supuestos del art. 308."),a("Para citar a declarar al imputado basta una mera intuición del Fiscal.",!1,"Falso. Se requieren elementos suficientes o indicios vehementes de la perpetración de un delito y motivo bastante para sospechar de su participación."),e("El Fiscal no pudo recibir la declaración del detenido dentro de las 24 horas. ¿Qué prevé el art. 308?",["Una prórroga por otro plazo igual","Una prórroga de hasta diez días, por decisión fiscal","Que la reciba la policía para no exceder el plazo","Que el plazo se suspenda hasta el día hábil siguiente"],"El plazo de 24 horas puede prorrogarse «por otro igual» cuando el Fiscal no pudo recibirla o cuando el imputado lo pide para proponer defensor."),a("Aun sin estado de sospecha, el Fiscal puede citar a una persona a prestar declaración informativa, con las garantías del imputado.",!0,"Verdadero. El art. 308 prevé la declaración informativa: la persona y su letrado tienen todas las garantías, derechos y deberes del imputado y del defensor.")]}),o({id:"u2-a308-l2",titulo:"Defensor presente y derecho al silencio",minutos:4,intro:{titulo:"Un acto de defensa, no de confesión",parrafos:["La declaración del imputado es, ante todo, un medio de defensa: allí conoce el hecho y la prueba en su contra y decide si habla o calla.","Debe recibirse previa notificación al defensor, bajo sanción de nulidad, y ningún interrogatorio puede tomarse en cuenta si el abogado no pudo asesorarlo sobre si le conviene declarar. Nunca bajo juramento, coacción, amenaza o engaño.","Una «declaración» tomada por la policía sin defensor no vale como declaración del imputado."],enLaPractica:"Si en la comisaría le hacen firmar a un detenido una «declaración espontánea» autoincriminatoria sin abogado, la defensa pide su nulidad y exclusión."},foco:"previa notificación al Defensor bajo sanción de nulidad",preguntas:[e("¿Qué pasa si se le recibe declaración sin notificar previamente al defensor?",["Es nula","Es válida si el imputado la firmó","Es válida si luego la ratifica en el juicio","Es nula sólo si se prueba un perjuicio concreto"],"El art. 308 exige la notificación previa al defensor bajo sanción de nulidad, y no vale ningún interrogatorio si el abogado no pudo asesorarlo."),a("El imputado declara bajo juramento de decir verdad.",!1,"Falso. Exigirle juramento lo obligaría a autoincriminarse; está prohibido."),r("Ordená cómo se desarrolla la declaración:",["Se notifica al defensor, que lo asesora antes del acto","Se le informa el hecho atribuido y la prueba en su contra","Se le hace saber que puede abstenerse de declarar","El imputado decide si declara o calla"],"Primero las garantías (defensor e información); después la decisión libre del imputado."),e("Un comisario le promete a un detenido que «si confiesa se va a su casa». ¿Qué problema hay?",["Es un medio prohibido para inducirlo a declarar contra su voluntad","Ninguno, si el detenido acepta libremente","Ninguno, si después confirma la confesión ante el Fiscal","Sólo afecta la credibilidad de la confesión, no su validez"],"El art. 310 prohíbe cualquier medio para obligarlo, inducirlo o determinarlo a declarar contra su voluntad, y sanciona su inobservancia con nulidad.")]})]}],caso:{id:"caso-u2",titulo:"La primera declaración",rol:"Defensa oficial",sede:"UFI de turno · Departamento Judicial Quilmes (caso ficticio)",hechos:["Lucas (19) fue aprehendido a las 23:40 en Bernal, señalado por una mujer que dice que le arrebató el celular empujándola contra una pared.","Lo trasladan a la comisaría. Vos sos la defensora oficial de turno."],etapas:[{id:"e1",momento:"Comisaría · 00:30 h",situacion:"Un oficial le acerca a Lucas un papel para que firme una «declaración espontánea» donde reconoce el hecho. Todavía no habló con vos.",pregunta:"¿Qué le indicás a Lucas?",opciones:[{texto:"Que no firme nada: la declaración válida se presta ante el Fiscal, con defensor presente (arts. 60 y 308).",puntaje:2,devolucion:"Correcto. La policía no puede recibir declaración al imputado; una confesión sin defensor es nula y no puede valorarse."},{texto:"Que firme si lo que dice el papel es verdad, así colabora.",puntaje:0,devolucion:"Nunca. Sin defensor y ante la policía, ese acto viola sus garantías y podría usarse en su contra."},{texto:"Que firme, pero que después pida una copia.",puntaje:0,devolucion:"La copia no sana el vicio: el problema es firmar una autoincriminación sin asistencia letrada."}],normas:["Art. 60 CPPBA","Art. 308 CPPBA","Art. 18 CN"]},{id:"e2",momento:"Domingo · 50 horas después",situacion:"Lucas sigue detenido y todavía nadie de la UFI le recibió declaración. No hubo ningún pedido de prórroga fundado.",pregunta:"¿Qué hacés?",opciones:[{texto:"Acudo al Juez de Garantías para que controle la legalidad de la detención por exceso del plazo del art. 308 (y, si hace falta, interpongo hábeas corpus).",puntaje:2,devolucion:"Bien. Vencido el plazo legal (24 h, más una eventual prórroga), la detención se vuelve irregular y el Juez de Garantías debe intervenir."},{texto:"Espero: el lunes seguro lo llaman.",puntaje:0,devolucion:"La libertad no espera al lunes. El plazo corre también el fin de semana."},{texto:"Pido la nulidad de toda la causa y el sobreseimiento.",puntaje:1,devolucion:"El exceso afecta la legitimidad de la detención, pero no borra automáticamente el hecho investigado. La vía es el control de la detención."}],normas:["Art. 308 CPPBA","Arts. 405 y ss. CPPBA (hábeas corpus)"]},{id:"e3",momento:"Audiencia de declaración en la UFI",situacion:"La Fiscal informa el hecho y menciona un video de una cámara municipal que todavía no está agregado a la causa.",pregunta:"¿Qué aconsejás?",opciones:[{texto:"Que se abstenga de declarar por ahora, hasta conocer toda la prueba; su silencio no puede perjudicarlo.",puntaje:2,devolucion:"Estrategia sólida. Puede declarar después cuantas veces quiera, cuando la defensa conozca el video."},{texto:"Que declare sí o sí, porque callar «lo hace quedar culpable».",puntaje:0,devolucion:"Falso: el silencio es un derecho y no genera presunción en su contra."},{texto:"Que declare solo, sin vos, para mostrar buena fe.",puntaje:0,devolucion:"La declaración sin defensor es nula. Además, lo deja sin asesoramiento."}],normas:["Arts. 60 y 308 CPPBA"]},{id:"e4",momento:"Calificación legal",situacion:"La Fiscal califica el hecho. Según la denuncia, hubo un empujón para quitarle el teléfono.",pregunta:"Con esos hechos, ¿qué figura del Código Penal se discute?",opciones:[{texto:"Robo simple (art. 164 CP): apoderamiento con violencia física en las personas.",puntaje:2,devolucion:"Exacto. La violencia física para apoderarse convierte el hurto en robo. La defensa puede discutir si hubo realmente violencia (si no, sería hurto, art. 162)."},{texto:"Hurto (art. 162 CP), porque el celular vale poco.",puntaje:1,devolucion:"El valor de la cosa no define la figura. Si se prueba el empujón, hay violencia y la figura es robo; el hurto sería la hipótesis defensiva si no hubo violencia."},{texto:"Robo agravado por el uso de arma (art. 166 inc. 2 CP).",puntaje:0,devolucion:"No hubo ningún arma. La pared no es un arma en el sentido del art. 166."}],normas:["Art. 162 CP","Art. 164 CP"]}],cierre:{titulo:"Defensa desde el minuto cero",texto:"Protegiste a Lucas desde la comisaría: sin declaración policial, con control del plazo de 24 horas, con un uso estratégico del silencio y con una discusión precisa de la calificación. Esa calificación (robo simple, máximo 6 años) será clave para su excarcelación y para una eventual probation."}}},b={id:"u3",numero:3,titulo:"Medidas de coerción y prisión preventiva",subtitulo:"Cuándo se puede restringir la libertad durante el proceso",etapa:"Medidas cautelares",color:"violeta",icono:"🔐",temas:[{articuloId:"cppba-144",relacionados:["cppba-3"],falloClave:{tribunal:"Corte Suprema de Justicia de la Nación",caso:"«Verbitsky, Horacio s/ hábeas corpus»",anio:"2005",resumen:"Ante la sobrepoblación de detenidos en comisarías y cárceles bonaerenses, el CELS presentó un hábeas corpus colectivo. La Corte fijó estándares mínimos de detención y exhortó a la Provincia a adecuar su legislación sobre excarcelación y prisión preventiva a los estándares constitucionales e internacionales.",regla:"La prisión preventiva es excepcional y sólo cautelar; las condiciones de detención deben respetar la dignidad humana. Las normas provinciales deben ajustarse a la Constitución y a los tratados.",nota:"Síntesis didáctica (Fallos 328:1146, 3/5/2005). Es un fallo central para entender las reformas al régimen de coerción del CPPBA.",enlaces:[n.verbitsky],ambito:"nacional"},fallosRelacionados:[{tribunal:"Suprema Corte de Justicia de la Provincia de Buenos Aires",caso:"«Verbitsky» · ejecución del fallo de la Corte (P. 83.909)",anio:"2022",resumen:"Después de que la CSJN reclamara en 2021 que se ejecutara efectivamente su sentencia de 2005, la SCBA puso en marcha un programa de cumplimiento con medidas concretas para revertir el «estado de cosas inconstitucional» de las personas privadas de libertad en la Provincia.",regla:"Los jueces deben revisar periódicamente la situación de cada persona detenida y preferir medidas menos lesivas cuando el caso lo permita (arts. 159, 160, 163 y 168 bis); la prisión preventiva no puede funcionar como pena anticipada; no pueden alojarse en comisarías menores, embarazadas ni enfermos; y deben priorizarse los juicios de quienes llevan más tiempo en prisión preventiva.",nota:"Síntesis de la resolución del 3/5/2022.",enlaces:[n.scbaVerbitsky2022],ambito:"bonaerense"}],lecciones:[o({id:"u3-a144-l1",titulo:"La libertad es la regla",minutos:3,intro:{titulo:"Principio general: libertad durante el proceso",parrafos:["Por el principio de inocencia, el imputado transita el proceso en libertad. El art. 144 lo dice sin vueltas: permanecerá libre, salvo que se den los supuestos que la ley prevé para decidir lo contrario.","La libertad sólo puede restringirse cuando sea absolutamente indispensable para tres fines: averiguar la verdad, desarrollar el procedimiento y aplicar la ley.","Y como toda norma que restringe la libertad, se interpreta en forma restrictiva (art. 3 CPPBA)."],enLaPractica:"Cuando la UFI pide una detención, el Juez de Garantías debe partir de la libertad y exigir que el Fiscal demuestre por qué es indispensable restringirla."},foco:"El imputado permanecerá en libertad durante la sustanciación del proceso penal",preguntas:[e("¿Cuál es la regla durante el proceso penal según el art. 144?",["La libertad del imputado","La detención hasta que preste declaración","La libertad bajo caución en todos los casos","La detención cuando el delito es grave"],"La regla es la libertad; las medidas de coerción son la excepción."),r("Ordená los fines que pueden justificar restringir la libertad (art. 144):",["Asegurar la averiguación de la verdad","Asegurar el desarrollo del procedimiento","Asegurar la aplicación de la ley"],"Los tres fines son procesales. Ninguno es castigar o calmar a la opinión pública."),a("Se puede detener a un imputado durante el proceso para que «empiece a pagar» por el delito.",!1,"Falso. Eso sería una pena anticipada, contraria al principio de inocencia."),i("Completá el art. 144.","La libertad sólo podrá ser restringida cuando fuere ___ indispensable.",["absolutamente","razonablemente","estrictamente","prudencialmente"],"La letra es «absolutamente indispensable»: un estándar más exigente que «razonable» o «prudencial».")]})]},{articuloId:"cppba-146",lecciones:[o({id:"u3-a146-l1",titulo:"Condiciones de toda medida de coerción",minutos:4,intro:{titulo:"Los cuatro filtros (art. 146)",parrafos:["Antes de ordenar cualquier medida de coerción, el juez verifica condiciones que vienen del derecho cautelar:","1) Apariencia de responsabilidad: indicios serios de que el imputado participó. 2) Peligro cierto de frustración del proceso si no se adopta la medida. 3) Proporcionalidad entre la medida y lo que se quiere proteger. 4) Contracautela, cuando la medida la piden el particular damnificado o el actor civil.","Y la medida se ordena a pedido de parte: el juez no actúa por iniciativa propia."],enLaPractica:"Encarcelar preventivamente por un delito que, aun con condena, terminaría con una pena en suspenso, es desproporcionado: la cautela no puede ser más grave que la eventual pena."},preguntas:[e("¿Cuál de estas NO es una condición del art. 146?",["Que la víctima preste conformidad con la medida","Apariencia de responsabilidad","Peligro cierto de frustración de los fines del proceso","Proporcionalidad entre la medida y el objeto de tutela"],"La víctima puede ser oída (por ejemplo, en la audiencia del art. 168 bis), pero su conformidad no es una condición legal. La contracautela, en cambio, sí se exige cuando la medida la pide el particular damnificado o el actor civil."),a("El Juez de Garantías puede imponer una medida de coerción de oficio, sin pedido de nadie.",!1,"Falso. El art. 146 exige pedido de parte: es coherente con el sistema acusatorio."),e("¿Qué significa «proporcionalidad» en materia cautelar?",["Que la medida no sea más gravosa que lo necesario ni que la pena esperable","Que dure lo mismo que el mínimo de la escala penal","Que guarde relación con la magnitud del daño a la víctima","Que sea idéntica para todos los coimputados"],"La proporcionalidad impide que la cautela supere el reproche que se espera al final del proceso.")]})]},{articuloId:"cppba-148",relacionados:["cppba-171"],lecciones:[o({id:"u3-a148-l1",titulo:"Peligro de fuga",minutos:4,intro:{titulo:"¿Se va a escapar?",parrafos:["Los peligros procesales son la única razón válida para encarcelar durante el proceso. El primero es el peligro de fuga.","El art. 148 da pautas para evaluarlo: el arraigo en el país (domicilio, familia, trabajo; dar un domicilio inexacto puede ser un indicio de fuga), la pena que se espera, la actitud frente al daño y a la víctima, y el comportamiento en este u otros procesos (por ejemplo, rebeldías anteriores).","Ninguna pauta funciona sola ni en abstracto: hay que analizarlas en el caso concreto."],enLaPractica:"Un imputado con domicilio verificado, empleo formal y que se presentó espontáneamente a la UFI tiene un fuerte argumento contra el peligro de fuga."},foco:"Para merituar sobre el peligro de fuga se tendrán en cuenta especialmente las siguientes circunstancias",preguntas:[e("¿Cuál de estos datos REDUCE el peligro de fuga?",["Domicilio fijo, familia a cargo y trabajo estable","Haber estado prófugo en otra causa","Tener pasaporte y pasajes al exterior","Haber dado un domicilio falso"],"El arraigo (domicilio, familia, trabajo) es la pauta central del inc. 1 del art. 148."),a("Haber sido declarado rebelde en un proceso anterior puede valorarse para el peligro de fuga.",!0,"Verdadero: el comportamiento en otro procedimiento anterior indica la voluntad de someterse o no al proceso."),a("Que el imputado haya dado un domicilio inexacto puede configurar un indicio de fuga.",!0,"Verdadero: el inc. 1 del art. 148 lo prevé expresamente al regular el arraigo."),i("Completá la pauta del inciso 2.","Para el peligro de fuga se tiene en cuenta la ___ que se espera como resultado del procedimiento.",["pena","caución","reparación","audiencia"],"Una pena alta esperable puede incentivar la fuga, pero por sí sola no alcanza: debe combinarse con datos concretos del caso.")]}),o({id:"u3-a148-l2",titulo:"Peligro de entorpecimiento",minutos:3,intro:{titulo:"¿Va a obstaculizar la investigación?",parrafos:["El segundo peligro procesal es el entorpecimiento probatorio. Requiere una grave sospecha, basada en datos concretos, de que el imputado destruirá o falsificará prueba, influirá sobre coimputados, testigos o peritos, o inducirá a otros a hacerlo.","Este peligro suele disminuir a medida que avanza la investigación: una vez que la prueba está asegurada, ya no hay qué entorpecer."],enLaPractica:"Si el imputado llamó a la víctima para que «retire la denuncia», hay un indicio concreto de entorpecimiento que el Fiscal puede invocar."},preguntas:[r("Ordená las conductas que integran el peligro de entorpecimiento como aparecen en el art. 148:",["Destruir, modificar, ocultar o falsificar elementos de prueba","Influir sobre coimputados, testigos o peritos","Inducir a otros a realizar esos comportamientos"],"Primero la prueba material, después las personas, y por último la inducción a terceros."),a("El peligro de entorpecimiento puede fundarse en una sospecha genérica de que «podría» influir en testigos.",!1,"Falso. Hace falta una grave sospecha basada en circunstancias concretas del caso."),e("¿Por qué el peligro de entorpecimiento suele disminuir con el tiempo?",["Porque una vez asegurada la prueba ya no hay qué entorpecer","Porque caduca al vencer los cuatro meses de la IPP","Porque sólo puede invocarse antes de la declaración del imputado","Porque después del primer mes se presume a favor del imputado"],"Cuando la prueba ya fue recolectada (pericias, testimonios), el riesgo de obstrucción es menor.")]}),o({id:"u3-a148-l3",titulo:"Pautas generales y sus límites",minutos:3,intro:{titulo:"Gravedad del hecho: ¿alcanza?",parrafos:["El primer párrafo del art. 148 permite valorar también las características del hecho, la posible reincidencia, las condiciones personales y si el imputado gozó de excarcelaciones anteriores.","Pero la jurisprudencia es clara: esas pautas sirven para presumir un peligro, no para reemplazarlo. La sola gravedad del delito o la «alarma social» no justifican una prisión preventiva."],enLaPractica:"Si un Fiscal pide la preventiva «por la conmoción social que generó el hecho», la defensa responde que la alarma social no es un peligro procesal."},preguntas:[a("La «alarma social» o la repercusión mediática de un caso es un peligro procesal que justifica la prisión preventiva.",!1,"Falso. Los únicos peligros procesales son la fuga y el entorpecimiento; la alarma social no está entre ellos."),e("¿Cómo deben usarse las pautas del primer párrafo del art. 148 (características del hecho, reincidencia, etc.)?",["Como indicios para evaluar un peligro concreto, no como presunciones automáticas","Como causales automáticas de prisión preventiva","Como presunciones que el imputado debe desvirtuar","Como pautas que sólo rigen para reincidentes"],"Sirven para fundar «fundadamente» la presunción de fuga o entorpecimiento en el caso concreto."),i("Completá.","Puede valorarse si el imputado hubiere gozado de ___ anteriores.",["excarcelaciones","suspensiones de juicio a prueba","condenas condicionales","morigeraciones"],"Haber incumplido excarcelaciones anteriores puede indicar falta de voluntad de someterse al proceso.")]})]},{articuloId:"cppba-154",relacionados:["cppba-153"],lecciones:[o({id:"u3-a154-l1",titulo:"Flagrancia y aprehensión",minutos:4,intro:{titulo:"Detener sin orden judicial",parrafos:["Como regla, privar de la libertad requiere orden judicial. La excepción más importante es la flagrancia: la policía (y en ciertos casos un particular) puede aprehender sin orden.","Hay flagrancia cuando el autor es sorprendido cometiendo el hecho o inmediatamente después; mientras es perseguido por la fuerza pública, el ofendido o el público; o mientras tiene objetos o presenta rastros que hagan presumir que acaba de participar en un delito.","El aprehendido debe quedar de inmediato a disposición de la autoridad judicial: desde la restricción de la libertad corren las 24 horas del art. 308 para recibirle declaración."],enLaPractica:"En la Provincia, muchos casos de flagrancia tramitan por un procedimiento especial más rápido, con audiencias orales ante el Juez de Garantías."},foco:"es sorprendido en el momento de cometerlo o inmediatamente después",preguntas:[e("¿Cuál de estas situaciones NO es flagrancia?",["Detener a alguien una semana después porque «tiene cara conocida»","Sorprenderlo mientras rompe la vidriera","Detenerlo mientras huye perseguido por la víctima","Encontrarlo segundos después con el objeto robado en la mano"],"La flagrancia exige inmediatez entre el hecho y la aprehensión. Una semana después ya no hay flagrancia."),r("Ordená cronológicamente un procedimiento por flagrancia:",["La policía sorprende al autor cometiendo el hecho","Lo aprehende sin orden judicial","Lo pone de inmediato a disposición de la autoridad judicial","El Fiscal le recibe declaración en el plazo legal"],"La aprehensión sin orden es excepcional y debe ser inmediatamente controlada por la autoridad judicial."),a("En flagrancia, la policía puede mantener al aprehendido sin avisar al Fiscal hasta terminar el sumario.",!1,"Falso. El aprehendido debe quedar de inmediato a disposición de la autoridad judicial; además, desde la restricción de la libertad corre el plazo de 24 horas del art. 308."),i("Completá la definición del art. 154.","También hay flagrancia mientras es ___ por la fuerza pública, el ofendido o el público.",["perseguido","identificado","señalado","buscado"],"La persecución ininterrumpida mantiene la flagrancia."),a("Si el delito es de instancia privada y quien puede promover la acción no denuncia en el acto, el aprehendido debe ser liberado.",!0,"Verdadero: lo dice el último párrafo del art. 153. Sin la instancia de la víctima no puede seguir la persecución.")]})]},{articuloId:"cppba-157",relacionados:["cppba-158","cppba-159"],falloClave:{tribunal:"Comisión Interamericana de Derechos Humanos",caso:"Informe 86/09 «Peirano Basso» (Uruguay)",anio:"2009",resumen:"La CIDH sistematizó los estándares de la prisión preventiva: es excepcional, debe fundarse en fines procesales concretos (fuga o entorpecimiento), respetar la proporcionalidad y revisarse periódicamente.",regla:"No puede fundarse la prisión preventiva sólo en la gravedad del delito o en la pena en expectativa: hace falta acreditar un riesgo procesal concreto en el caso.",nota:"Síntesis didáctica del informe de fondo (adoptado como Informe 35/07 y publicado como 86/09). Los tribunales bonaerenses citan con frecuencia estos estándares.",enlaces:[n.peiranoBasso],ambito:"interamericano"},lecciones:[o({id:"u3-a157-l1",titulo:"Requisitos de la prisión preventiva",minutos:4,intro:{titulo:"Cuatro requisitos, todos juntos",parrafos:["La detención se convierte en prisión preventiva sólo si se reúnen conjuntamente cuatro requisitos: 1) que esté justificada la existencia del delito; 2) que el imputado haya declarado (o se haya negado); 3) que haya elementos de convicción suficientes o indicios vehementes de que probablemente es autor o partícipe; 4) que concurran los presupuestos del art. 171 para denegar la excarcelación, es decir, peligros procesales.","Si falta uno solo, no hay preventiva: corresponde la libertad o una medida menos gravosa. Antes de resolver, el juez fija una audiencia oral y pública si una parte la pide o si él lo decide (art. 168 bis)."],enLaPractica:"El Juez de Garantías bonaerense resuelve la preventiva a pedido del Fiscal, muchas veces en audiencia oral, y su decisión es apelable ante la Cámara de Garantías."},foco:"cuando medien conjuntamente los siguientes requisitos",preguntas:[r("Ordená los requisitos de la prisión preventiva según el art. 157:",["Existencia del delito justificada","Declaración del imputado recibida (o negativa a prestarla)","Elementos de convicción suficientes sobre su probable autoría o participación","Presupuestos del art. 171 para denegar la excarcelación"],"Es el orden del art. 157: primero el hecho, después la persona, y por último el riesgo procesal (remisión al art. 171)."),a("Puede dictarse prisión preventiva sin haber recibido declaración al imputado ni haberle dado la oportunidad de hacerlo.",!1,"Falso. La declaración (o la negativa a prestarla) es requisito del inc. 2: garantiza que el imputado haya podido defenderse antes."),e("Hay prueba sólida del hecho y de la autoría, pero el imputado tiene arraigo y la prueba ya está asegurada. ¿Procede la preventiva?",["No: falta el peligro procesal","Sí: alcanza con la prueba del hecho y la autoría","Sí, si la pena en expectativa supera ocho años","Sí, si el particular damnificado lo pide"],"Los requisitos son conjuntos. Sin peligro procesal concreto (inc. 4, remisión al art. 171) no hay prisión preventiva."),e("¿Qué prevé el art. 168 bis antes de resolver la prisión preventiva?",["Una audiencia oral y pública, a pedido de parte o por decisión del juez, notificada con 48 horas","Una vista escrita a la defensa por cinco días","Una audiencia reservada en la que no participa la víctima","Ninguna audiencia: el juez decide sobre el expediente"],"En la audiencia hablan, en ese orden y hasta 15 minutos cada uno, el Fiscal, la víctima o particular damnificado, la defensa y el imputado. A los ocho meses sin debate puede pedirse una nueva.")]})]},{articuloId:"cppba-159",relacionados:["cppba-163","cppba-160"],lecciones:[o({id:"u3-a157-l2",titulo:"Alternativas a la prisión preventiva",minutos:5,intro:{titulo:"Antes que la cárcel, otras opciones",parrafos:["El art. 159 obliga al juez («impondrá») a usar alternativas en lugar de la prisión cuando se trate de personas mayores de 70 años, con una enfermedad incurable en período terminal, embarazadas o con hijos menores de 5 años, siempre que el peligro pueda evitarse con una medida menos gravosa o con control electrónico.","Fuera de esos casos, el art. 163 permite morigerar la coerción en forma excepcional, previa vista al Fiscal, si el peligro puede evitarse con una medida menos gravosa (prisión domiciliaria, salidas laborales, internación terapéutica). La víctima debe ser informada y puede pedir ser oída.","Y el art. 160 enumera condiciones para la libertad: presentaciones periódicas, prohibición de salir de un ámbito o de comunicarse con ciertas personas, caución, entre otras."],enLaPractica:"En un caso con riesgo de contacto con la víctima, una prohibición de acercamiento con tobillera electrónica puede neutralizar el peligro sin encarcelar."},foco:"el juez de garantías impondrá tales alternativas en lugar de la prisión",preguntas:[e("El único riesgo es que el imputado contacte a la víctima. ¿Qué medida es la más adecuada?",["Prohibición de comunicarse con la víctima, con control si hace falta","Prisión preventiva en una unidad penal","Caución real elevada","Presentaciones semanales en la comisaría, sin otra restricción"],"La medida debe ser idónea y la menos lesiva para neutralizar ese riesgo concreto."),e("Una imputada embarazada tiene un riesgo de fuga que puede neutralizarse con monitoreo electrónico. ¿Qué debe hacer el juez?",["Imponer la alternativa en lugar de la prisión: el art. 159 dice «impondrá»","Elegir libremente entre la prisión preventiva y la alternativa","Dictar la preventiva y evaluar después una morigeración","Concederla sólo si el Fiscal presta conformidad"],"Para mayores de 70 años, enfermos terminales, embarazadas o madres de hijos menores de 5 años, si el peligro puede evitarse con una medida menos gravosa, la alternativa es obligatoria."),i("Completá el art. 159.","Siempre que el peligro de fuga o de entorpecimiento probatorio pudiera razonablemente evitarse por aplicación de otra medida ___ gravosa para el imputado.",["menos","igualmente","proporcionalmente","más"],"La alternativa menos gravosa se impone si alcanza para neutralizar el peligro."),e("Un imputado de 40 años, sin hijos pequeños, pide una morigeración. ¿Qué norma la habilita?",["El art. 163: excepcionalmente, previa vista al Fiscal, si una medida menos gravosa evita el peligro","El art. 159, que rige para cualquier imputado","Ninguna: sólo procede para los casos del art. 159","El art. 169, como una forma de excarcelación"],"El art. 163 (Ley 15.232) admite la morigeración fuera de los supuestos del art. 159, en forma excepcional y fundada; la resolución es apelable y se informa a la víctima."),a("La prisión domiciliaria con control es una de las formas de atenuar la coerción.",!0,"Verdadero: el art. 163 la enumera junto con el encarcelamiento con salidas y el ingreso en una institución educadora o terapéutica.")]})]},{articuloId:"cppba-158",lecciones:[o({id:"u3-a158-l1",titulo:"El auto de prisión preventiva",minutos:3,intro:{titulo:"Plazo y contenido del auto",parrafos:["El Fiscal debe pedir la prisión preventiva dentro de los quince días (prorrogables por igual plazo) desde que se efectivizó la detención, y el juez dicta el auto dentro del quinto día de esa solicitud.","Según el art. 158, el auto debe: 1) expresar cuáles son los elementos que acreditan el delito y su autor o partícipe; 2) si toma en cuenta la declaración del imputado, extraer la parte pertinente; 3) si se apoya en testimonios o pericias, mencionar sintéticamente lo que resulta de ellos; 4) si usa otros elementos probatorios, señalar cuáles son y cómo resultan acreditados.","Es decir: no alcanza con afirmar que hay prueba; hay que mostrarla."],enLaPractica:"Al apelar una preventiva ante la Cámara de Garantías, la defensa revisa punto por punto si el auto explica de qué prueba surgen el hecho y la autoría, y si se dictó dentro del plazo."},foco:"dentro del plazo de quince (15) días prorrogables por igual plazo",preguntas:[i("Completá el art. 158.","La solicitud del Agente Fiscal debe presentarse dentro del plazo de ___ prorrogables por igual plazo, a contar de la detención.",["quince (15) días","cinco (5) días","diez (10) días","treinta (30) días"],"Quince días desde que se efectivizó la detención, prorrogables por igual plazo. Los cinco días son el plazo del juez para resolver."),e("El Fiscal pidió la prisión preventiva. ¿En qué plazo debe dictarse el auto?",["Dentro del quinto día de la solicitud","Dentro de las 24 horas","Dentro de los quince días de la solicitud","Antes de la elevación a juicio, sin plazo fijo"],"Art. 158: el auto «será dictado dentro del quinto día de la solicitud del Agente Fiscal»."),e("¿A pedido de quién se dicta el auto de prisión preventiva?",["Del Agente Fiscal","Del Juez de Garantías, de oficio","Del Fiscal General departamental","De la Policía que intervino"],"El art. 158 lo dice expresamente: se dicta «a solicitud del Agente Fiscal» (coherente con el art. 146: las medidas se ordenan a pedido de parte)."),e("¿Qué debe expresar el auto?",["Cuáles son los elementos de los que resultan acreditados el delito y su autor o partícipe","La pena que se impondrá en la sentencia","La calificación definitiva que regirá en el juicio","El monto de la caución para excarcelarlo"],"Es el inc. 1 del art. 158. La pena se fija recién en la sentencia."),a("Si el auto se apoya en declaraciones testimoniales, basta con citarlas sin decir qué surge de ellas.",!1,"Falso. El art. 158 inc. 3 exige mencionar sintéticamente lo que resulta de las pruebas testimoniales o periciales.")]})]}],caso:{id:"caso-u3",titulo:"Flagrancia en la estación",rol:"Juez/a de Garantías",sede:"Juzgado de Garantías · Departamento Judicial Lomas de Zamora (caso ficticio)",hechos:["Diego (34) fue aprehendido en la estación de Banfield por un policía que lo persiguió sin perderlo de vista, segundos después de que arrebatara una billetera.","Tiene domicilio verificado, trabaja en una verdulería del barrio, tiene dos hijos y no registra antecedentes. Declaró ante la UFI asistido por su defensor.","El Fiscal te pide la prisión preventiva. Vos decidís."],etapas:[{id:"e1",momento:"Control de la aprehensión",situacion:"La defensa plantea que Diego fue detenido sin orden judicial.",pregunta:"¿La aprehensión fue legítima?",opciones:[{texto:"Sí: fue perseguido inmediatamente después del hecho por la fuerza pública; hay flagrancia (arts. 153 y 154).",puntaje:2,devolucion:"Correcto. La persecución inmediata e ininterrumpida configura flagrancia y habilita la aprehensión sin orden."},{texto:"No: toda detención requiere orden judicial previa.",puntaje:0,devolucion:"La flagrancia es justamente la excepción a la orden judicial previa."},{texto:"Sólo habría sido legítima si la hacía la víctima.",puntaje:0,devolucion:"La policía tiene el deber de aprehender en flagrancia; los particulares, la facultad."}],normas:["Arts. 153 y 154 CPPBA"]},{id:"e2",momento:"Pedido de preventiva",situacion:"El Fiscal funda su pedido en «la gravedad del hecho y la alarma social que generan los robos en la estación».",pregunta:"¿Cómo resolvés?",opciones:[{texto:"Rechazo el pedido: la alarma social no es un peligro procesal y Diego tiene arraigo; no se acreditó riesgo de fuga ni de entorpecimiento.",puntaje:2,devolucion:"Muy bien. Faltan los peligros procesales concretos (arts. 144, 148 y 157 inc. 4)."},{texto:"Hago lugar: los robos en la estación son un problema grave.",puntaje:0,devolucion:"Eso convertiría la preventiva en una herramienta de política de seguridad, ajena a sus fines procesales."},{texto:"Hago lugar por 30 días, «para que reflexione».",puntaje:0,devolucion:"Sería una pena anticipada, prohibida por el principio de inocencia."}],normas:["Art. 144 CPPBA","Art. 148 CPPBA","Art. 157 CPPBA"]},{id:"e3",momento:"Nueva prueba",situacion:"Dos días después, la víctima declara que Diego la llamó por teléfono para pedirle que «no siga con la denuncia».",pregunta:"¿Qué medida es la más adecuada?",opciones:[{texto:"Impongo prohibición de contacto con la víctima y presentaciones periódicas (art. 159), advirtiendo que su incumplimiento puede llevar a una medida más grave.",puntaje:2,devolucion:"Excelente. Hay un indicio concreto de entorpecimiento, pero una medida menos gravosa puede neutralizarlo."},{texto:"Dicto prisión preventiva de inmediato.",puntaje:1,devolucion:"El riesgo existe, pero si una alternativa lo neutraliza, el juez debe preferirla (art. 159)."},{texto:"No hago nada: llamar a la víctima no es relevante.",puntaje:0,devolucion:"Influir sobre la víctima o testigos es exactamente el peligro de entorpecimiento del art. 148."}],normas:["Art. 148 CPPBA","Art. 159 CPPBA"]}],cierre:{titulo:"Coerción con límites",texto:"Controlaste la aprehensión, exigiste peligros procesales concretos y elegiste la medida menos gravosa capaz de neutralizar el riesgo. Así trabaja un Juez de Garantías: la libertad es la regla y la coerción, la excepción fundada."}}},v={id:"u4",numero:4,titulo:"Excarcelación y eximición de prisión",subtitulo:"Recuperar (o conservar) la libertad durante el proceso",etapa:"Medidas cautelares",color:"verde",icono:"🗝️",temas:[{articuloId:"cppba-169",relacionados:["cp-26"],falloClave:{tribunal:"Corte Suprema de Justicia de la Nación",caso:"«Nápoli, Erika Elizabeth y otros»",anio:"1998",resumen:"Una ley había excluido de la excarcelación a los imputados de ciertos delitos, sólo por el tipo de delito. La Corte la declaró inconstitucional.",regla:"El legislador no puede convertir determinados delitos en «inexcarcelables» en abstracto: la restricción de la libertad durante el proceso debe apoyarse en la verificación de peligros procesales en el caso concreto.",nota:"Síntesis didáctica (Fallos 321:3630, 22/12/1998). En la misma línea, el plenario «Díaz Bessone» (Cámara Federal de Casación, 2008) sostuvo que la pena en expectativa no basta por sí sola para denegar la libertad.",enlaces:[n.napoli],ambito:"nacional"},fallosRelacionados:[{tribunal:"Suprema Corte de Justicia de la Provincia de Buenos Aires",caso:"«Carrascosa» (P. 125.776)",anio:"2016",resumen:"Un imputado condenado a prisión perpetua por sentencia no firme llevaba más de cinco años en prisión preventiva (morigerada) y reclamaba su cese por exceso del plazo razonable. La SCBA rechazó el recurso por insuficiente: la defensa no rebatió todos los fundamentos de la Casación, que había valorado el avance de la causa (condenas en dos instancias), su complejidad, la gravedad del hecho y la pena en expectativa junto con las pautas del art. 148.",regla:"La razonabilidad de la prisión preventiva se mide en el caso concreto: grado de avance del proceso (incluida una condena no firme), complejidad, naturaleza del hecho y pena en expectativa, como indicadores del peligro de fuga del art. 148. Si cambia la situación (por ejemplo, se revoca la condena), puede volver a pedirse.",nota:"Síntesis de la sentencia del 1/6/2016 (rechazo por mayoría de fundamentos). Contrastala con «Nápoli»: la pena en expectativa sirve como indicio en el caso, nunca como regla abstracta.",enlaces:[n.scbaCarrascosa],ambito:"bonaerense"}],lecciones:[o({id:"u4-a169-l1",titulo:"¿Qué es la excarcelación?",minutos:3,intro:{titulo:"De la detención a la libertad caucionada",parrafos:["La excarcelación es el instituto por el cual el imputado que ya está detenido recupera su libertad mientras sigue el proceso, prestando una caución (juratoria, personal o real).","No es un «perdón» ni significa que la causa termina: el proceso continúa y el imputado debe presentarse cada vez que lo citen.","Su primo es la eximición de prisión (art. 185): se pide ANTES de ser detenido."],enLaPractica:"El pedido de excarcelación se presenta ante el Juez de Garantías, tramita por incidente y la resolución es apelable ante la Cámara de Garantías."},preguntas:[e("¿Quién puede pedir la excarcelación?",["El imputado que se encuentra detenido","Quien teme ser detenido en una causa determinada","El condenado con sentencia firme","El imputado citado a declarar en libertad"],"La excarcelación presupone una detención. Quien todavía no está detenido pide la eximición de prisión (art. 185); el condenado con sentencia firme, en cambio, discute su libertad en la ejecución (libertad condicional)."),a("Si el imputado es excarcelado, la causa penal queda terminada.",!1,"Falso. El proceso sigue; sólo cambia la situación de libertad del imputado."),i("Completá.","El excarcelado debe prestar una ___ que asegure que se presentará al proceso.",["caución","contracautela","reparación del daño","declaración indagatoria"],"La caución puede ser juratoria, personal o real. La contracautela es otra cosa: la presta el particular damnificado o el actor civil que pide una medida (art. 146 inc. 4)."),e("Una persona se entera de que la investigan por una causa determinada y teme ser detenida. ¿Qué puede pedir?",["La eximición de prisión","La excarcelación","Un hábeas corpus preventivo","La suspensión del juicio a prueba"],"El art. 185 permite pedir la eximición de prisión a toda persona que se considere imputada en una causa penal determinada; se resuelve en tres días. El hábeas corpus procede contra restricciones o amenazas ilegales o arbitrarias, no contra una investigación regular.")]}),o({id:"u4-a169-l2",titulo:"La pena en juego: hasta 8 años",minutos:4,intro:{titulo:"Inciso 1: el máximo de la escala",parrafos:["El primer supuesto mira la escala penal en abstracto: procede la excarcelación si el delito imputado tiene una pena cuyo máximo no supere los ocho años de prisión o reclusión.","En el concurso real (varios hechos), se mira la pena aplicable al concurso, que tampoco debe superar los ocho años (inc. 2).","Por eso la calificación legal que elige el Fiscal es tan importante: cambia la escala y, con ella, la libertad. Ojo: en delitos con violencia mediante armas de fuego o con intervención de menores de 18 años, se toma la escala que resulta de los arts. 41 bis y 41 quater CP."],enLaPractica:"Un robo simple (art. 164 CP: 1 mes a 6 años) entra en el inciso 1; un robo con arma (art. 166 inc. 2: 5 a 15 años) no."},foco:"cuyo máximo no supere los ocho (8) años de prisión o reclusión",preguntas:[e("Imputación por robo simple (art. 164 CP: un mes a seis años). ¿Entra en el inc. 1 del art. 169?",["Sí: el máximo (6 años) no supera los 8","No: hubo violencia en las personas","Sólo si es probable una condena condicional","Sólo si el Fiscal presta conformidad"],"Se compara el MÁXIMO de la escala con el tope de 8 años. La condena condicional probable es otro supuesto (inc. 3), para cuando el máximo supera los 8."),e("Imputación por robo con arma (art. 166 inc. 2 CP: cinco a quince años). ¿Entra en el inc. 1?",["No: el máximo (15) supera los 8 años","Sí: el mínimo (5) es menor a 8","Sí, si el imputado no tiene antecedentes","Depende de que el arma sea de fuego"],"El máximo de 15 años supera el tope del inc. 1. Habrá que analizar otros incisos (por ejemplo, el de la condena condicional probable)."),i("Completá el inciso 1.","Procede cuando el delito tenga prevista una pena cuyo máximo no supere los ___ de prisión o reclusión.",["ocho (8) años","seis (6) años","tres (3) años","quince (15) años"],"El tope vigente es de ocho años en el máximo de la escala (Ley 14.128; antes eran seis)."),e("Dos hurtos en concurso real (art. 162 CP: máximo 2 años cada uno). ¿Procede la excarcelación por la escala?",["Sí: la pena aplicable al concurso (máximo 4 años) no supera los 8 (inc. 2)","No: el concurso real no es excarcelable","Sólo si cada hecho, por separado, no supera 3 años","Se toma sólo el delito más grave y se ignora el otro"],"En el concurso real el máximo se forma sumando los máximos (art. 55 CP): 2 + 2 = 4 años, por debajo del tope de 8 del inc. 2."),e("En delitos cometidos con violencia mediante armas de fuego, ¿qué escala se usa para resolver la excarcelación?",["La que resulta de aplicar los arts. 41 bis y 41 quater del CP","La del delito sin agravantes","La de la tentativa del delito","La mitad del máximo previsto"],"Es el párrafo final del art. 169 (también para delitos con intervención de menores de 18 años)."),a("Para el inciso 1 se mira el mínimo de la escala penal.",!1,"Falso: se mira el máximo de la escala en abstracto.")]}),o({id:"u4-a169-l3",titulo:"Condena condicional probable",minutos:4,intro:{titulo:"Inciso 3: el pronóstico de pena",parrafos:["Aunque el máximo supere los ocho años, la excarcelación procede si es probable que, en caso de condena, se aplique una condena de ejecución condicional (en suspenso).","Para eso hay que mirar el art. 26 del Código Penal: la condena condicional cabe en la primera condena a prisión que no exceda de tres años.","Entonces la pregunta clave es: ¿el mínimo de la escala permite una pena de 3 años o menos? ¿Es su primera condena? ¿Las circunstancias del hecho y personales lo hacen probable?"],enLaPractica:"Robo con arma de utilería (art. 166 último párrafo: 3 a 10 años): el mínimo es 3, así que una primera condena podría ser en suspenso. El inc. 3 es la puerta de la defensa."},foco:"resultare probable que pueda aplicársele condena de ejecución condicional",preguntas:[e("¿Qué artículo del Código Penal define cuándo cabe la condena de ejecución condicional?",["El art. 26 CP","El art. 27 bis CP","El art. 76 bis CP","El art. 13 CP"],"El art. 26 CP: primera condena a prisión que no exceda de tres años. El 27 bis regula las reglas de conducta, el 76 bis la probation y el 13 la libertad condicional."),i("Completá el art. 26 CP.","En los casos de primera condena a pena de prisión que no exceda de ___, el tribunal podrá dejar en suspenso su cumplimiento.",["tres años","dos años","cuatro años","seis años"],"Tres años es el límite de la condenación condicional."),e("Robo con arma de fuego apta (escala de 6 años y 8 meses a 20 años). ¿Puede invocarse el inc. 3?",["No: el mínimo supera 3 años, así que la condena condicional es imposible","Sí: para el inc. 3 sólo importa el máximo","Sí, si el imputado no tiene antecedentes","Sí, si ofrece una caución real"],"Si el mínimo de la escala supera 3 años, ninguna condena podrá ser en suspenso: el inc. 3 queda descartado."),a("El inciso 3 exige analizar las circunstancias del hecho y las características y antecedentes personales del imputado.",!0,"Verdadero. No basta con la escala: el pronóstico de condena condicional se apoya en el caso concreto.")]}),o({id:"u4-a169-l4",titulo:"Sobreseimiento, agotamiento y plazo razonable",minutos:4,intro:{titulo:"Cuando el tiempo o la causa ya no justifican el encierro",parrafos:["Otros incisos del art. 169 atienden a situaciones en que la detención perdió sentido: sobreseimiento no firme (inc. 4); haber agotado en detención el máximo de la pena según la calificación del requerimiento de citación a juicio (inc. 5); estar en condiciones de obtener la libertad condicional o asistida (inc. 6); o una sentencia no firme absolutoria, en suspenso, ya agotada o que permite la libertad condicional (incs. 8 a 10).","Y el inc. 11 recoge el plazo razonable: procede si la prisión preventiva excede el plazo del art. 7.5 de la Convención Americana, teniendo en cuenta la gravedad del delito, la pena probable y la complejidad del proceso.","Son reglas de proporcionalidad: la prisión preventiva nunca puede durar más que la pena posible."]},foco:"excede el plazo razonable a que se refiere el artículo 7º inciso 5) de la Convención Americana de Derechos Humanos",preguntas:[a("Si el imputado ya estuvo detenido el máximo de la pena prevista para el delito, debe recuperar su libertad.",!0,"Verdadero. Seguir detenido superaría cualquier condena posible: es desproporcionado."),e("El imputado fue sobreseído pero el Fiscal apeló. ¿Puede ser excarcelado?",["Sí: el sobreseimiento no firme habilita la excarcelación (inc. 4)","No, hasta que la Cámara resuelva la apelación","Sólo si el delito tiene pena máxima de hasta 8 años","Sólo si el Fiscal desiste de la apelación"],"El sobreseimiento, aun no firme, debilita al extremo el fundamento de la detención."),r("Ordená de menor a mayor exigencia temporal estos supuestos de agotamiento:",["Tiempo de detención que habría permitido la libertad condicional","Tiempo de detención igual al máximo de la pena prevista"],"La libertad condicional se obtiene antes del agotamiento total de la pena (por ejemplo, a los 2/3 en penas temporales de más de 3 años, art. 13 CP)."),e("Un hombre lleva cuatro años en prisión preventiva por un hecho simple, sin fecha de juicio a la vista. ¿Qué inciso del art. 169 invocás?",["El inc. 11: la preventiva excede el plazo razonable (art. 7.5 CADH)","El inc. 1, porque pasó mucho tiempo desde el hecho","El inc. 4, por equiparación al sobreseimiento","Ninguno: el plazo razonable sólo se discute en casación"],"El inc. 11 permite excarcelar cuando la prisión preventiva excede el plazo razonable, valorando gravedad, pena probable y complejidad. También corresponde revisar los plazos fatales del art. 141.")]})]},{articuloId:"cppba-171",relacionados:["cppba-148"],lecciones:[o({id:"u4-a171-l1",titulo:"Denegatoria: peligros procesales",minutos:4,intro:{titulo:"El límite de la excarcelación",parrafos:["Aunque se cumpla algún inciso del art. 169, la excarcelación se deniega si hay indicios vehementes de que el imputado tratará de eludir la acción de la justicia o entorpecer la investigación (art. 171).","Esos peligros pueden inferirse de las circunstancias del art. 148 (arraigo, pena esperada, comportamiento procesal, etc.). Además, en casos de tenencia o portación ilegítima de arma de fuego, el juez puede considerar que concurren si el imputado intentó eludir a la policía, evadir un control o resistirse al procedimiento.","Al revés también vale: si el delito tiene una pena alta, la defensa puede igualmente discutir la libertad demostrando que no hay peligros concretos."],enLaPractica:"Un imputado de hurto (máximo 2 años) que ya se fugó en otras dos causas puede ver denegada su excarcelación pese a la pena baja: hay indicios vehementes de fuga."},foco:"indicios vehementes de que el imputado tratará de eludir la acción de la justicia o entorpecer la investigación",preguntas:[e("¿Qué exige el art. 171 para denegar la excarcelación?",["Indicios vehementes de fuga o de entorpecimiento de la investigación","Que la pena máxima supere los ocho años","Que el imputado registre antecedentes penales","Que la víctima se oponga en la audiencia"],"El art. 171 se basa en los peligros procesales. La pena, los antecedentes o la oposición de la víctima pueden ser datos a valorar, pero no bastan por sí solos."),a("Un delito con pena máxima de 2 años es siempre excarcelable, aunque el imputado tenga varias fugas previas.",!1,"Falso. Los indicios vehementes de fuga permiten denegar la excarcelación aun en delitos leves."),i("Completá.","La existencia de los peligros procesales podrá inferirse de las circunstancias previstas en el artículo ___.",["148","146","157","163"],"El art. 171 remite a las pautas del art. 148."),e("Una ley declara «inexcarcelable» un delito sólo por su tipo, sin mirar el caso. ¿Qué dijo la CSJN en un supuesto así?",["Es inconstitucional: hay que verificar peligros procesales concretos («Nápoli»)","Es válida, porque el legislador decide","Es válida si la pena supera 8 años","Es válida si la ley prevé otra caución"],"En «Nápoli» (1998) la Corte invalidó la exclusión de la excarcelación por la sola naturaleza del delito."),e("Detienen a un hombre que portaba sin autorización un arma de fuego y que intentó escapar de un control policial. ¿Qué permite el art. 171?",["Que el juez considere que hay peligro procesal y deniegue la excarcelación","Nada: la portación tiene pena baja, así que la excarcelación es obligatoria","Dictar la prisión preventiva sin audiencia ni pedido fiscal","Denegarla sólo si el arma estaba cargada"],"El segundo párrafo del art. 171 (Ley 14.517) autoriza a considerar que concurren los peligros procesales cuando, en esos supuestos, el imputado intentó eludir el accionar policial, evadir un control o resistirse al procedimiento.")]})]},{articuloId:"cp-166",relacionados:["cp-164","cp-162"],lecciones:[o({id:"u4-cp166-l1",titulo:"Hurto, robo y robo agravado (CP)",minutos:5,intro:{titulo:"Las figuras que más llegan a las UFI",parrafos:["Hurto (art. 162 CP): apoderarse ilegítimamente de una cosa mueble ajena. Pena: 1 mes a 2 años.","Robo (art. 164 CP): lo mismo, pero con fuerza en las cosas o violencia física en las personas. Pena: 1 mes a 6 años.","Robo agravado (art. 166 CP): 5 a 15 años si hay lesiones graves o gravísimas por la violencia, o si se usan armas (o en despoblado y en banda). Con arma de fuego, la escala sube un tercio; con arma de fuego no apta o de utilería, baja a 3 a 10 años."],enLaPractica:"Estas escalas deciden, en la práctica, si el imputado queda libre (art. 169), si puede pedir probation (art. 76 bis CP) y si cabe un juicio abreviado."},preguntas:[e("¿Qué diferencia al robo del hurto?",["La fuerza en las cosas o la violencia física en las personas","El valor de lo sustraído","Que la víctima esté presente","Que intervenga más de un autor"],"El art. 164 CP agrega la fuerza o violencia al apoderamiento ilegítimo del art. 162."),r("Ordená de menor a mayor pena máxima:",["Hurto (art. 162)","Robo simple (art. 164)","Robo con arma de utilería (art. 166, último párrafo)","Robo con arma (art. 166 inc. 2)"],"Máximos: 2, 6, 10 y 15 años (y más aún con arma de fuego apta)."),i("Completá el art. 164 CP.","Será reprimido con prisión de un mes a ___, el que se apoderare ilegítimamente de una cosa mueble con fuerza en las cosas o con violencia física en las personas.",["seis años","dos años","quince años","tres años"],"El robo simple tiene una escala de un mes a seis años."),a("Según el art. 166 CP, si el arma de fuego utilizada no puede tenerse por apta para el disparo, la pena es de tres a diez años.",!0,"Verdadero: es el último párrafo del art. 166 (también para armas de utilería).")]})]}],caso:{id:"caso-u4",titulo:"El arma de utilería",rol:"Defensa particular",sede:"Juzgado de Garantías · Departamento Judicial San Martín (caso ficticio)",hechos:["Sofía (26) está detenida, imputada de robar una mochila amenazando a la víctima con una réplica de pistola. La pericia confirmó que era un arma de utilería.","No tiene antecedentes, vive con su madre y estudia enfermería. El Fiscal calificó el hecho como robo con arma de utilería (art. 166, último párrafo, CP)."],etapas:[{id:"e1",momento:"Escrito de excarcelación",situacion:"Tenés que elegir en qué inciso del art. 169 apoyar el pedido.",pregunta:"¿Cuál es el fundamento más sólido?",opciones:[{texto:"El inc. 3: el máximo (10 años) supera los 8, pero el mínimo (3 años) y su falta de antecedentes hacen probable una condena condicional (art. 26 CP).",puntaje:2,devolucion:"Excelente lectura combinada CPPBA + CP. Es el camino técnico correcto."},{texto:"El inc. 1, porque el delito tiene una pena «baja».",puntaje:0,devolucion:"El inc. 1 exige un máximo de hasta 8 años; aquí el máximo es 10."},{texto:"Ninguno: el robo con arma nunca es excarcelable.",puntaje:0,devolucion:"No existen delitos inexcarcelables en abstracto («Nápoli»). Además, el inc. 3 encaja."}],normas:["Art. 169 CPPBA","Art. 26 CP","Art. 166 CP"]},{id:"e2",momento:"Contestación del Fiscal",situacion:"El Fiscal se opone: dice que «no se verificó el domicilio» de Sofía.",pregunta:"¿Cómo respondés?",opciones:[{texto:"Ofrezco acreditar el arraigo: constatación del domicilio, certificado de alumna regular y testimonio de su madre (art. 148 inc. 1).",puntaje:2,devolucion:"Bien. Convertís la objeción en prueba de arraigo, que es la pauta central contra el peligro de fuga."},{texto:"Respondo que el domicilio es irrelevante.",puntaje:0,devolucion:"Es muy relevante: el arraigo es la primera pauta del art. 148."},{texto:"Desisto del pedido hasta el juicio.",puntaje:0,devolucion:"Dejarías a Sofía presa sin necesidad. La objeción se resuelve acreditando el arraigo."}],normas:["Art. 148 CPPBA","Art. 171 CPPBA"]},{id:"e3",momento:"Resolución",situacion:"El Juez concede la excarcelación. Falta fijar la caución. Sofía no tiene ingresos propios.",pregunta:"¿Qué caución pedís?",opciones:[{texto:"Una caución juratoria (o personal razonable), acorde a su situación económica.",puntaje:2,devolucion:"Correcto. La caución no puede ser de imposible cumplimiento: si no, la libertad concedida sería ilusoria."},{texto:"Una caución real de varios millones de pesos, para mostrar seriedad.",puntaje:0,devolucion:"Una caución inalcanzable equivale a negar la excarcelación por razones económicas."},{texto:"Ninguna: que salga sin compromiso alguno.",puntaje:1,devolucion:"La excarcelación requiere alguna caución; la juratoria es la menos gravosa."}],normas:["Arts. 169 a 196 CPPBA"]},{id:"e4",momento:"Variante del caso",situacion:"Imaginá que la pericia hubiera concluido que el arma era de fuego y apta para el disparo.",pregunta:"¿Qué cambia?",opciones:[{texto:"La escala sube un tercio (6 años y 8 meses a 20): el inc. 3 queda descartado y sólo puede discutirse la ausencia de peligros procesales y medidas alternativas.",puntaje:2,devolucion:"Exacto. Con un mínimo superior a 3 años la condena condicional es imposible, pero la libertad sigue dependiendo de los peligros concretos."},{texto:"Nada: el inc. 3 sigue aplicando.",puntaje:0,devolucion:"Con un mínimo de 6 años y 8 meses no hay condena condicional posible."},{texto:"El delito pasa a ser automáticamente inexcarcelable.",puntaje:0,devolucion:"La gravedad no sustituye el análisis de los peligros procesales concretos."}],normas:["Art. 166 CP","Arts. 159 y 171 CPPBA"]}],cierre:{titulo:"Libertad bien argumentada",texto:"Combinaste el CPPBA con el Código Penal: la escala del art. 166, el pronóstico de condena condicional del art. 26 y el análisis de arraigo del art. 148. Así se litiga una excarcelación en los juzgados de garantías bonaerenses."}}},g={id:"u5",numero:5,titulo:"Nulidades y medios de prueba",subtitulo:"Cómo se prueba y qué pasa cuando se violan las formas",etapa:"Medios de prueba",color:"rosa",icono:"🔎",temas:[{articuloId:"cppba-201",relacionados:["cppba-202","cppba-203"],falloClave:{tribunal:"CSJN y tribunales bonaerenses (línea reiterada)",caso:"Principio de trascendencia: «no hay nulidad sin perjuicio»",resumen:"La jurisprudencia exige, para declarar una nulidad, que quien la plantea indique qué perjuicio concreto le causó el vicio y qué defensas se vio privado de oponer. La nulidad no se declara en el solo interés de la ley.",regla:"La nulidad es la última ratio: procede cuando el vicio produce un perjuicio real a una parte o afecta garantías constitucionales; si el acto puede subsanarse o cumplió su finalidad, se mantiene.",nota:"Síntesis de una línea jurisprudencial consolidada, hoy recogida en el segundo párrafo del art. 201. Para un escrito, buscá precedentes concretos en JUBA (SCBA) y en la base de la CSJN.",enlaces:[],ambito:"nacional"},lecciones:[o({id:"u5-a201-l1",titulo:"Taxatividad y perjuicio",minutos:4,intro:{titulo:"Sólo es nulo lo que la ley dice… y si causa perjuicio",parrafos:["El art. 201 fija el principio de taxatividad: la inobservancia de las formas sólo hace nulos los actos en los supuestos expresamente determinados por el código (por ejemplo, la declaración del imputado sin notificar al defensor, art. 308).","Y agrega el principio de trascendencia: no se declara la nulidad si el vicio no produjo ni pudo producir perjuicio para quien la alega o para aquel en cuyo favor se estableció. Por eso el art. 205 exige expresar el motivo y el perjuicio, bajo sanción de inadmisibilidad."],enLaPractica:"Antes de plantear una nulidad, buscá en el código la frase «bajo sanción (o pena) de nulidad» o una garantía constitucional afectada. Si no está, el planteo probablemente sea rechazado."},foco:"sólo los hará nulos en los supuestos expresamente determinados por este Código",preguntas:[e("¿Cuándo la inobservancia de las formas hace nulo un acto (art. 201)?",["Sólo en los supuestos expresamente determinados por el Código","Siempre que se viole cualquier norma procesal","Cuando el juez lo considere conveniente para el proceso","Cuando ambas partes lo consientan"],"Es el principio de taxatividad (o especificidad)."),a("Aunque haya un vicio previsto bajo sanción de nulidad, no se declara si no produjo ni pudo producir perjuicio.",!0,"Verdadero: es el segundo párrafo del art. 201 (principio de trascendencia, «no hay nulidad sin perjuicio»)."),i("Completá.","Las nulidades se rigen por el principio de ___: sólo las que la ley prevé expresamente.",["taxatividad","trascendencia","conservación","convalidación"],"Taxatividad o especificidad: la ley enumera las causales. La trascendencia es el otro requisito: que haya perjuicio."),e("El acta de una testimonial tiene mal escrita la fecha, pero el testigo, las partes y el contenido están claros. La defensa pide la nulidad sin indicar perjuicio. ¿Qué corresponde?",["Rechazarla: no se alega ni existe perjuicio (arts. 201 y 205)","Declararla: toda acta con errores es nula","Declararla de oficio por violar normas constitucionales","Diferirla hasta la sentencia"],"El art. 205 exige expresar los motivos y el perjuicio bajo sanción de inadmisibilidad, y el art. 201 impide declarar nulidades sin perjuicio.")]}),o({id:"u5-a201-l2",titulo:"Nulidades generales y de oficio",minutos:4,intro:{titulo:"Las que siempre importan",parrafos:["El art. 202 agrega nulidades de orden general: las referidas al nombramiento, capacidad y constitución del juez o tribunal; a la intervención del Ministerio Público cuando es obligatoria; y a la intervención, asistencia y representación del imputado y de las partes civiles.","Las nulidades que implican violación de normas constitucionales deben declararse de oficio, en cualquier estado y grado del proceso, fundando el perjuicio (art. 203). Las demás deben plantearse a tiempo (art. 205): las de la IPP, durante la IPP.","El órgano que comprueba un vicio procura sanearlo sin retroceder a etapas cumplidas (art. 206); y el acto queda subsanado si no se pidió su saneamiento en término, si se aceptaron sus efectos o si cumplió su fin."],enLaPractica:"Si se descubre en el juicio que el imputado nunca tuvo defensor en un acto central de la IPP, el Tribunal debe declarar la nulidad aunque nadie la haya pedido."},preguntas:[e("¿Cuál de estos vicios es una nulidad de carácter general?",["Falta de asistencia del imputado por su defensor en un acto en que es obligatoria","Que el Fiscal no firmó una providencia de mero trámite","Que la víctima no estuvo presente en una testimonial","Que un auto se notificó un día después de dictado"],"La asistencia y representación del imputado está expresamente protegida por el art. 202."),a("Las nulidades que implican violación de normas constitucionales deben declararse de oficio en cualquier estado y grado del proceso.",!0,"Verdadero, según el art. 203, «con obligación de fundar el motivo del perjuicio»."),e("Una nulidad se produjo durante la IPP y no afecta normas constitucionales. ¿Hasta cuándo puede articularse?",["Durante la IPP","Hasta la sentencia definitiva","Hasta la audiencia preliminar del juicio","Sólo dentro de las 24 horas del acto"],"Art. 205 inc. 1, bajo sanción de caducidad. Las 24 horas son el plazo para pedir el saneamiento del acto (art. 206)."),r("Ordená de la regla a la excepción:",["Regla: sólo hay nulidad si la ley la prevé expresamente (art. 201)","Nulidades de orden general (art. 202)","Declaración de oficio si afectan normas constitucionales (art. 203)"],"Del principio de taxatividad a las nulidades absolutas, que operan aun sin pedido de parte.")]})]},{articuloId:"cppba-209",lecciones:[o({id:"u5-a209-l1",titulo:"Libertad probatoria",minutos:3,intro:{titulo:"Se puede probar por cualquier medio… lícito",parrafos:["Todo hecho relacionado con el objeto del proceso puede probarse por cualquiera de los medios previstos en el código: testigos, peritos, documentos, reconocimientos, careos, etc.","Incluso se pueden usar otros medios (registros de cámaras, informes de telefonía…), siempre que no supriman garantías constitucionales ni afecten el sistema institucional. Y se puede limitar la prueba manifiestamente superabundante."],enLaPractica:"Las imágenes del Centro de Monitoreo municipal o de una cámara de un comercio son prueba válida en una IPP bonaerense, aunque el código no las mencione expresamente."},foco:"pueden ser acreditados por cualquiera de los medios de prueba",preguntas:[a("Un video de una cámara de seguridad puede usarse como prueba aunque el CPPBA no regule expresamente ese medio.",!0,"Verdadero: rige la libertad probatoria, con los límites de la ley y las garantías."),e("¿Cuál es un límite a la libertad probatoria?",["Que el medio no suprima garantías constitucionales","Que el medio esté expresamente enumerado en el Código","Que lo ofrezca el Fiscal durante la IPP","Que se produzca ante el Juez de Garantías"],"El art. 209 admite otros medios siempre que no supriman garantías constitucionales de las personas ni afecten el sistema institucional."),i("Completá.","Se podrán utilizar otros medios de prueba siempre que no supriman ___ de las personas o afecten el sistema institucional.",["garantías constitucionales","formas procesales","derechos de la víctima","facultades del Fiscal"],"Las garantías constitucionales son el límite infranqueable."),a("Si todos los intervinientes están de acuerdo, puede prescindirse de probar un hecho notorio y declararlo comprobado.",!0,"Verdadero: último párrafo del art. 209, que también permite limitar la prueba manifiestamente superabundante.")]})]},{articuloId:"cppba-210",lecciones:[o({id:"u5-a210-l1",titulo:"Valoración: convicción sincera y razonada",minutos:3,intro:{titulo:"Libertad para valorar, obligación de explicar",parrafos:["Según el art. 210, para valorar la prueba sólo se exige la expresión de la convicción sincera sobre la verdad de los hechos juzgados, con desarrollo escrito de las razones que llevan a esa convicción. Rige en todas las etapas, salvo en el juicio por jurados, donde rige la íntima convicción.","No hay pruebas con valor fijado por ley (prueba tasada), pero el juez tampoco puede decidir sin explicar: la jurisprudencia lo asimila a la sana crítica racional, es decir, razonar con lógica, experiencia y conocimientos científicos."],enLaPractica:"En casación, una sentencia que no explica por qué descartó la versión del imputado puede anularse por arbitrariedad en la valoración de la prueba."},foco:"convicción sincera sobre la verdad de los hechos juzgados",preguntas:[e("¿Qué exige el art. 210 para valorar la prueba?",["La convicción sincera sobre los hechos, con desarrollo escrito de sus razones","La íntima convicción, sin necesidad de fundar","Un valor fijo asignado por la ley a cada prueba","La coincidencia de la mayoría de los testigos"],"El art. 210 combina libertad de valoración con deber de motivación: convicción sincera más desarrollo escrito de las razones."),i("Completá el art. 210.","Para la valoración de la prueba sólo se exige la expresión de la convicción ___ sobre la verdad de los hechos juzgados.",["sincera","íntima","razonable","plena"],"Convicción sincera, con desarrollo escrito de las razones que la sostienen."),a("En el sistema del CPPBA, una confesión vale automáticamente como prueba plena.",!1,"Falso. Ninguna prueba tiene valor tasado: también la confesión se valora junto con las demás, y el juez debe explicar sus razones."),r("Ordená los sistemas de valoración del más rígido al más libre:",["Prueba tasada (legal)","Convicción razonada / sana crítica","Íntima convicción sin fundamentos"],"El CPPBA exige convicción sincera con fundamentos escritos (asimilable a la sana crítica); la íntima convicción es la del jurado popular."),e("En un juicio por jurados, ¿qué regla de valoración rige para el veredicto?",["La íntima convicción","La convicción sincera con fundamentos escritos","La prueba tasada","La sana crítica, con voto fundado de cada jurado"],"El art. 210 (Ley 14.543) exceptúa al juicio por jurados: allí rige la íntima convicción. El control se hace por las instrucciones del juez y por los motivos del art. 448 bis.")]})]},{articuloId:"cppba-211",falloClave:{tribunal:"CSJN y Corte Interamericana de Derechos Humanos",caso:"«Rayford» (CSJN, 1986) y «Fernández Prieto y Tumbeiro vs. Argentina» (Corte IDH, 2020)",resumen:"En «Rayford» la CSJN excluyó no sólo la prueba obtenida ilegalmente sino también la que derivaba de ella, salvo que existiera un cauce de investigación independiente. En «Fernández Prieto y Tumbeiro», la Corte IDH condenó a la Argentina por detenciones y requisas basadas en la «actitud sospechosa» de las personas, sin elementos objetivos.",regla:"La prueba obtenida con afectación de garantías y la que deriva directamente de ella carecen de eficacia (doctrina del «fruto del árbol venenoso»), salvo fuente independiente. Una requisa sin motivos objetivos previos es arbitraria.",nota:"Síntesis didáctica (Fallos 308:733; Corte IDH, sentencia del 1/9/2020, Serie C 411).",enlaces:[n.rayford,n.fernandezPrieto],ambito:"nacional"},lecciones:[o({id:"u5-a211-l1",titulo:"Regla de exclusión",minutos:4,intro:{titulo:"El Estado no puede beneficiarse de su propio ilícito",parrafos:["El art. 211 es breve y potente: carece de toda eficacia la prueba obtenida con afectación de garantías constitucionales.","Eso alcanza también a la prueba derivada («fruto del árbol venenoso»): si un allanamiento ilegal lleva a encontrar un objeto, y ese objeto lleva a un testigo, todo el «árbol» queda contaminado.","La excepción: si la misma prueba se habría obtenido por una fuente independiente y lícita, puede valorarse."],enLaPractica:"Requisas por «nerviosismo» o «actitud sospechosa» son planteos habituales de nulidad y exclusión ante los Juzgados de Garantías bonaerenses."},foco:"Carecerá de toda eficacia",preguntas:[e("La policía entró a una casa sin orden ni urgencia y encontró un celular robado. ¿Qué pasa con esa prueba?",["Carece de eficacia por violar la inviolabilidad del domicilio","Es válida si después el juez convalida el ingreso","Es válida si el imputado no protestó en el momento","Es válida si la víctima reconoce el celular"],"El hallazgo no convalida el ingreso ilegal. Rige el art. 211 y el art. 18 CN."),a("La prueba que deriva directamente de una prueba ilícita también debe excluirse, salvo fuente independiente.",!0,"Verdadero: es la doctrina del fruto del árbol venenoso («Rayford»)."),e("¿Qué es la «fuente independiente»?",["Un cauce lícito de investigación que habría llevado a la misma prueba sin depender de la ilegalidad","La prueba obtenida por un particular y no por la policía","La prueba que el imputado no objetó en término","La que se obtiene con una orden judicial dictada después del hallazgo"],"Si la prueba se obtiene por un camino autónomo y lícito, la exclusión no la alcanza."),i("Completá el art. 211.","Carecerá de toda eficacia la prueba obtenida con afectación de ___.",["garantías constitucionales","formas procesales","reglas de cadena de custodia","derechos de la víctima"],"La regla de exclusión protege las garantías constitucionales.")]})]}],caso:{id:"caso-u5",titulo:"La requisa por «nerviosismo»",rol:"Defensa oficial",sede:"Juzgado de Garantías · Departamento Judicial Mar del Plata (caso ficticio)",hechos:["Kevin (20) caminaba por el centro de Mar del Plata. Dos policías lo detuvieron porque «se mostró nervioso al ver el patrullero». Lo requisaron sin testigos y le encontraron un celular con pedido de secuestro.","Con ese dato fueron a su casa y su hermano de 15 años les abrió la puerta. Adentro encontraron otros dos celulares robados."],etapas:[{id:"e1",momento:"Análisis de la requisa",situacion:"El acta policial dice textualmente: «se mostró nervioso y esquivo, por lo que se procedió a su requisa».",pregunta:"¿Qué planteo hacés?",opciones:[{texto:"Nulidad de la requisa y exclusión del celular: el nerviosismo no es un motivo objetivo previo que justifique una requisa sin orden.",puntaje:2,devolucion:"Correcto. Es la línea de la Corte IDH en «Fernández Prieto y Tumbeiro» y de la regla de exclusión del art. 211."},{texto:"Ninguno: si encontraron un celular robado, la requisa estaba justificada.",puntaje:0,devolucion:"El resultado no convalida el procedimiento: los motivos deben existir ANTES de la requisa."},{texto:"Sólo pedir que se corrija el acta para agregar testigos.",puntaje:0,devolucion:"El problema no es formal: es la falta de causa legítima para afectar la libertad y la intimidad."}],normas:["Art. 211 CPPBA","Arts. 219 a 225 CPPBA","Art. 18 CN"]},{id:"e2",momento:"El ingreso al domicilio",situacion:"La policía sostiene que el hermano de Kevin «autorizó» el ingreso.",pregunta:"¿Qué sostenés?",opciones:[{texto:"El ingreso es inválido: no hubo orden judicial y el consentimiento de un menor de 15 años, sin informarle su derecho a negarse, no es válido. Además, deriva de la requisa ilegal.",puntaje:2,devolucion:"Muy bien: doble vicio. Los celulares del domicilio son fruto del árbol venenoso."},{texto:"El ingreso es válido porque alguien abrió la puerta.",puntaje:0,devolucion:"Abrir la puerta no equivale a un consentimiento libre e informado para un registro."},{texto:"El ingreso es válido pero la prueba hay que «valorarla con cuidado».",puntaje:1,devolucion:"La prueba obtenida con afectación de garantías no se valora con cuidado: se excluye."}],normas:["Art. 211 CPPBA","Art. 18 CN"]},{id:"e3",momento:"Oportunidad del planteo",situacion:"Te preguntás cuándo y ante quién plantear las nulidades.",pregunta:"¿Cuál es la vía correcta?",opciones:[{texto:"Plantearlas durante la IPP ante el Juez de Garantías y, si no prosperan, reeditar la cuestión de validez de los actos en la audiencia preliminar del juicio (art. 338).",puntaje:2,devolucion:"Correcto. Plantear temprano evita preclusiones; la audiencia preliminar permite discutir la validez constitucional de los actos de la IPP."},{texto:"Esperar a la sentencia y plantearlo directamente ante la Suprema Corte.",puntaje:0,devolucion:"Saltearías instancias y te arriesgarías a que se considere consentido el acto."},{texto:"Hacer una denuncia administrativa contra los policías y nada más.",puntaje:1,devolucion:"Puede hacerse, pero no resuelve la situación procesal de Kevin: la nulidad se plantea en el proceso."}],normas:["Arts. 201 a 208 CPPBA","Art. 338 CPPBA"]},{id:"e4",momento:"Prueba independiente",situacion:"Una de las víctimas había identificado a Kevin días antes en un video municipal, en una investigación iniciada por su denuncia y sin relación con la requisa.",pregunta:"¿Qué pasa con esa prueba?",opciones:[{texto:"Puede valorarse: proviene de una fuente independiente y lícita.",puntaje:2,devolucion:"Exacto. La exclusión alcanza a lo derivado de la ilegalidad, no a cauces autónomos."},{texto:"También debe excluirse porque todo el caso está contaminado.",puntaje:0,devolucion:"La regla de exclusión no borra prueba que se obtuvo por un camino lícito e independiente."},{texto:"Sólo vale si Kevin la reconoce.",puntaje:0,devolucion:"Su validez no depende del reconocimiento del imputado."}],normas:["Art. 211 CPPBA","Art. 210 CPPBA"]}],cierre:{titulo:"Garantías que filtran la prueba",texto:"Aplicaste la regla de exclusión con sus matices: requisas sin motivos objetivos, consentimientos inválidos, prueba derivada y fuente independiente. Es uno de los litigios más frecuentes en las audiencias de garantías."}}},f={id:"u6",numero:6,titulo:"IPP y elevación a juicio",subtitulo:"De la investigación a la acusación",etapa:"Investigación Penal Preparatoria",color:"turquesa",icono:"🧭",temas:[{articuloId:"cppba-266",relacionados:["cppba-56"],falloClave:{tribunal:"Corte Suprema de Justicia de la Nación",caso:"«Llerena, Horacio Luis»",anio:"2005",resumen:"En un proceso correccional, el mismo juez que había investigado era luego quien juzgaba. La Corte entendió que esa acumulación de funciones afectaba la garantía de imparcialidad.",regla:"Quien investiga no debe juzgar. Por eso el modelo bonaerense separa al Fiscal (que investiga) del Juez de Garantías (que controla) y del tribunal de juicio (que decide).",nota:"Síntesis didáctica (Fallos 328:1491, 17/5/2005).",enlaces:[n.llerena],ambito:"nacional"},lecciones:[o({id:"u6-a266-l1",titulo:"Para qué sirve la IPP",minutos:4,intro:{titulo:"Cinco objetivos de la investigación",parrafos:["La Investigación Penal Preparatoria no busca condenar: busca reunir lo necesario para decidir si hay un caso para llevar a juicio.","Según el art. 266, debe: 1) comprobar si existe un hecho delictuoso; 2) establecer las circunstancias que lo califican, agravan, atenúan, justifican o inciden en su punibilidad; 3) individualizar a autores y partícipes; 4) conocer las condiciones personales del imputado; y 5) comprobar la extensión del daño.","Fijate que la IPP también busca lo que favorece al imputado (atenuantes, justificantes): es la objetividad del Fiscal en acción."],enLaPractica:"Al recibir una denuncia por lesiones, la UFI pide el informe médico (extensión del daño), cita testigos (autoría) y revisa si hubo una agresión previa de la víctima (posible legítima defensa)."},foco:"La Investigación Penal Preparatoria tendrá por finalidad",preguntas:[r("Ordená las finalidades de la IPP como aparecen en el art. 266:",["Comprobar si existe un hecho delictuoso","Establecer las circunstancias que lo califiquen, agraven, atenúen, justifiquen o incidan en su punibilidad","Individualizar a autores y partícipes","Verificar las condiciones personales del imputado","Comprobar la extensión del daño"],"Del hecho a las personas y, finalmente, al daño causado."),a("La IPP sólo busca pruebas en contra del imputado.",!1,"Falso. También debe establecer circunstancias que atenúen o justifiquen el hecho."),e("¿Cuál de estas NO es una finalidad de la IPP?",["Fijar la pena que corresponde al imputado","Individualizar a los autores y partícipes","Comprobar la extensión del daño","Verificar las condiciones personales del imputado"],"La IPP prepara el juicio; la pena la fija el tribunal de juicio en la sentencia. Las condiciones personales del imputado sí se investigan (inc. 4).")]}),o({id:"u6-a266-l2",titulo:"Quién hace qué en la IPP",minutos:3,intro:{titulo:"Fiscal, policía y Juez de Garantías",parrafos:["El Fiscal dirige la IPP y a la Policía en función judicial. La Policía realiza las diligencias urgentes y las que el Fiscal le encarga.","El Juez de Garantías no investiga: autoriza los actos que afectan derechos (allanamientos, intervenciones telefónicas, detenciones), resuelve la coerción y controla la legalidad.","La defensa puede proponer diligencias y controlar la prueba."]},preguntas:[e("El Fiscal necesita allanar un domicilio. ¿Quién lo autoriza?",["El Juez de Garantías, a pedido del Fiscal","El propio Fiscal, como director de la IPP","El Fiscal General departamental","La Cámara de Apelación y Garantías"],"Los actos que afectan garantías (domicilio, comunicaciones, libertad) requieren orden judicial."),i("Completá.","El Juez de Garantías ___ la IPP: no la dirige.",["controla","practica","acusa","sentencia"],"El control judicial es la contracara del poder investigador del Fiscal."),a("La defensa puede proponer diligencias durante la IPP.",!0,"Verdadero. La IPP es contradictoria en la medida de lo posible; la defensa propone medidas y controla la prueba.")]})]},{articuloId:"cppba-282",relacionados:["cppba-141"],lecciones:[o({id:"u6-a282-l1",titulo:"Duración de la IPP",minutos:3,intro:{titulo:"Cuatro meses (y prórrogas acotadas)",parrafos:["La IPP debe practicarse en cuatro meses desde la detención o la declaración del imputado (art. 308).","Si no alcanza, el propio Fiscal dispone la prórroga, en forma motivada y fundada, con conocimiento del Juez de Garantías: hasta dos meses más, según las causas de la demora. En casos excepcionales, justificados por su gravedad o difícil investigación, la prórroga puede llegar a seis meses."],enLaPractica:"Con detenido, la defensa controla los vencimientos (y el tope del art. 141): una prórroga sin motivación puede cuestionarse ante el Juez de Garantías."},foco:"en el plazo de cuatro (4) meses",preguntas:[i("Completá el art. 282.","La Investigación Penal Preparatoria deberá practicarse en el plazo de ___ a contar de la detención o declaración del imputado.",["cuatro (4) meses","seis (6) meses","dos (2) años","tres (3) meses"],"Cuatro meses es el plazo ordinario."),e("¿Quién dispone la prórroga de la IPP?",["El propio Fiscal, en forma motivada y con conocimiento del Juez de Garantías","El Juez de Garantías, a pedido del Fiscal","El Fiscal General, a pedido del Agente Fiscal","La Cámara de Garantías, de oficio"],"Según el art. 282, el Fiscal «dispondrá motivada y fundadamente su prórroga, con conocimiento del Juez de Garantías»."),i("Completá.","La prórroga ordinaria puede ser de hasta ___ más.",["dos (2) meses","seis (6) meses","un (1) año","quince (15) días"],"Hasta dos meses; sólo en casos excepcionales, por gravedad o difícil investigación, hasta seis meses."),r("Ordená el cómputo de la IPP:",["Detención o declaración del imputado","Vencen los 4 meses ordinarios","Prórroga motivada de hasta 2 meses","En casos excepcionales, prórroga de hasta 6 meses"],"La regla son 4 meses; las prórrogas deben motivarse y son cada vez más excepcionales.")]})]},{articuloId:"cppba-334",relacionados:["cppba-335","cppba-334-bis"],lecciones:[o({id:"u6-a334-l1",titulo:"La requisitoria fiscal",minutos:4,intro:{titulo:"La acusación que abre la puerta del juicio",parrafos:["Si el Fiscal estima contar con elementos suficientes para ejercer la acción, y no corresponde aplicar un criterio de oportunidad o un mecanismo de abreviación del proceso, formula por escrito su requisitoria de citación a juicio (art. 334).","Antes, si durante la IPP denegó diligencias propuestas por las partes, debe disponer el cierre de la etapa y notificarlo: en cinco días las partes pueden pedir al Fiscal General que revise esa denegatoria, y éste resuelve en 48 horas.","Según el art. 335, debe contener, bajo sanción de nulidad: los datos del imputado, una relación clara, precisa, circunstanciada y específica del hecho, los fundamentos de la acusación y la calificación legal; y aclarar si debe juzgarlo un Tribunal Criminal (con o sin jurados) o un Juez Correccional. Puede indicar una calificación alternativa.","La descripción del hecho es la base del principio de congruencia: no se podrá condenar por un hecho distinto."],enLaPractica:"Una requisitoria que dice sólo «el imputado robó», sin lugar, fecha, modo ni objeto, impide la defensa: puede pedirse su nulidad."},foco:"formular por escrito su requisitoria de citación a juicio",preguntas:[e("¿Qué debe contener la requisitoria de elevación a juicio?",["Datos del imputado, relación circunstanciada del hecho, fundamentos y calificación legal","Datos del imputado, calificación legal y pena que se pedirá en el juicio","Relación del hecho y la lista de testigos, sin calificación legal","Datos del imputado y transcripción de la declaración de la víctima"],"Son los requisitos del art. 335, exigidos bajo sanción de nulidad."),a("Si el Fiscal no tiene elementos suficientes para acusar, igual debe requerir la elevación a juicio.",!1,"Falso. El art. 334 condiciona la requisitoria a contar con elementos suficientes; si no los hay, por objetividad, debe pedir el sobreseimiento."),e("Durante la IPP, el Fiscal rechazó una pericia que propuso la defensa. Ahora quiere requerir la elevación. ¿Qué debe hacer antes?",["Cerrar la etapa y notificarlo, para que la defensa pueda pedir al Fiscal General que revise la denegatoria","Nada: la denegatoria sólo puede discutirse en el juicio","Pedir autorización al Juez de Garantías para no producirla","Producir la pericia de oficio aunque la considere inútil"],"Art. 334, segundo párrafo: cierre de la etapa, cinco días para pedir la revisión al Fiscal General y 48 horas para que éste resuelva."),a("Si el Fiscal pide el sobreseimiento y hay particular damnificado constituido, éste puede llegar a sostener la acusación a su costa.",!0,"Verdadero (art. 334 bis): si el Fiscal de Cámara mantiene el sobreseimiento, el particular damnificado tiene 15 días para requerir la elevación a juicio."),i("Completá el art. 335.","La relación del hecho debe ser clara, precisa, ___ y específica.",["circunstanciada","fundada","sucinta","motivada"],"Circunstanciada: con tiempo, lugar, modo y participación.")]})]},{articuloId:"cppba-336",relacionados:["cppba-337"],lecciones:[o({id:"u6-a336-l1",titulo:"Oposición y elevación",minutos:3,intro:{titulo:"La defensa tiene 15 días",parrafos:["Notificada la requisitoria, la defensa puede oponerse dentro de 15 días: pedir el sobreseimiento, el cambio de calificación legal u oponer excepciones.","El Juez de Garantías resuelve en cinco días. Si rechaza la oposición, eleva la causa a juicio por auto, apelable por el defensor que se opuso. Si no hubo oposición, la causa pasa al tribunal de juicio por simple decreto (art. 337)."],enLaPractica:"Si la prueba muestra legítima defensa (art. 34 inc. 6 CP), la defensa se opone a la elevación y pide el sobreseimiento por causa de justificación."},foco:"en el término de quince (15) días",preguntas:[i("Completá el art. 336.","El defensor podrá, en el término de ___, oponerse instando al sobreseimiento o el cambio de calificación legal.",["quince (15) días","cinco (5) días","diez (10) días","tres (3) días"],"Quince días para preparar una oposición fundada."),e("¿Qué puede pedir la defensa al oponerse?",["El sobreseimiento, el cambio de calificación u oponer excepciones","La nulidad de toda la IPP, sin otra alternativa","Que se reabra la IPP por seis meses más","La absolución, con valoración definitiva de la prueba"],"Son las pretensiones que prevé el art. 336."),e("¿Quién resuelve la oposición y en qué plazo?",["El Juez de Garantías, en cinco días","El Juez de Garantías, en quince días","El Tribunal en lo Criminal, en cinco días","La Cámara de Garantías, en diez días"],"Art. 337: el Juez de Garantías resuelve en cinco días; si rechaza la oposición, eleva la causa a juicio por auto."),a("Si la defensa no se opone, la causa se remite al tribunal de juicio por simple decreto.",!0,"Verdadero, según el art. 337."),a("La legítima defensa (art. 34 inc. 6 CP) puede fundar un pedido de sobreseimiento.",!0,"Verdadero: es una causa de justificación.")]})]}],caso:{id:"caso-u6",titulo:"Cuatro meses y contando",rol:"Agente Fiscal",sede:"UFI N.º 5 · Departamento Judicial La Plata (caso ficticio)",hechos:["A la salida de un boliche de La Plata, Tomás golpeó a Iván, que sufrió una fractura con incapacidad laboral de más de un mes (lesiones graves, art. 90 CP).","Tomás declaró hace cuatro meses: dice que Iván lo atacó primero con una botella.","Vos llevás la investigación."],etapas:[{id:"e1",momento:"Vencimiento del plazo",situacion:"Se cumplen 4 meses desde la declaración y falta la pericia médica definitiva y un video del local.",pregunta:"¿Qué hacés?",opciones:[{texto:"Dispongo una prórroga motivada de hasta 2 meses, con conocimiento del Juez de Garantías, explicando qué diligencias faltan (art. 282).",puntaje:2,devolucion:"Correcto. En el CPPBA la prórroga la dispone el propio Fiscal, en forma motivada y fundada, con conocimiento del Juez de Garantías."},{texto:"Sigo investigando sin pedir nada: los plazos son orientativos.",puntaje:0,devolucion:"El plazo de la IPP es legal: vencido, hace falta una prórroga motivada; si no, se expone la validez de lo actuado."},{texto:"Archivo la causa porque se venció el plazo.",puntaje:0,devolucion:"El vencimiento no impone un archivo automático: corresponde pedir prórroga o resolver con lo que hay."}],normas:["Art. 282 CPPBA"]},{id:"e2",momento:"El video del boliche",situacion:"El video muestra que Iván levantó una botella contra Tomás antes del golpe.",pregunta:"Como Fiscal objetivo, ¿qué hacés con esa prueba?",opciones:[{texto:"La incorporo y evalúo si hubo legítima defensa (art. 34 inc. 6 CP): la IPP también busca lo que justifica el hecho (art. 266 inc. 2).",puntaje:2,devolucion:"Excelente: criterio objetivo (art. 56) y finalidad amplia de la IPP."},{texto:"No la agrego porque perjudica la acusación.",puntaje:0,devolucion:"Ocultar prueba favorable viola la objetividad del Fiscal y el derecho de defensa."},{texto:"La agrego pero sin analizarla.",puntaje:1,devolucion:"Incorporarla está bien, pero el Fiscal debe valorarla para decidir si acusa o pide el sobreseimiento."}],normas:["Art. 56 CPPBA","Art. 266 CPPBA","Art. 34 inc. 6 CP"]},{id:"e3",momento:"Decisión final",situacion:"El video también muestra que, ya desarmado y en el piso, Iván recibió varios golpes más de Tomás.",pregunta:"¿Qué requerimiento corresponde?",opciones:[{texto:"Requisitoria de elevación a juicio con una relación circunstanciada del hecho y su calificación (art. 334), porque los golpes posteriores exceden la defensa.",puntaje:2,devolucion:"Bien. Cuando la agresión cesó, la necesidad de defenderse desaparece; los golpes posteriores pueden imputarse."},{texto:"Sobreseimiento total por legítima defensa.",puntaje:1,devolucion:"Puede discutirse para el primer golpe, pero los golpes posteriores, con Iván desarmado, no parecen necesarios."},{texto:"Una requisitoria que diga sólo «Tomás lesionó a Iván».",puntaje:0,devolucion:"Esa descripción no es circunstanciada y sería nula: impide la defensa."}],normas:["Art. 334 CPPBA","Art. 90 CP","Art. 34 inc. 6 CP"]},{id:"e4",momento:"Oposición de la defensa",situacion:"La defensa se opone dentro de los 15 días y pide el sobreseimiento.",pregunta:"¿Qué sigue?",opciones:[{texto:"El Juez de Garantías resuelve la oposición y, si la rechaza, eleva la causa a juicio.",puntaje:2,devolucion:"Exacto: es el control jurisdiccional de la acusación. Resuelve en cinco días y el auto de elevación es apelable por el defensor (arts. 336 y 337)."},{texto:"Como Fiscal, resuelvo yo la oposición.",puntaje:0,devolucion:"El Fiscal es parte: no puede decidir sobre la oposición a su propia acusación."},{texto:"La causa va directo al Tribunal de Casación.",puntaje:0,devolucion:"Casación revisa sentencias; la elevación la decide el Juez de Garantías."}],normas:["Arts. 336 y 337 CPPBA"]}],cierre:{titulo:"Investigar con objetividad",texto:"Gestionaste los plazos de la IPP, valoraste prueba de descargo y formulaste una acusación precisa. Un Fiscal objetivo no «gana» cuando condena: cumple cuando aplica correctamente la ley."}}},y={id:"u7",numero:7,titulo:"Juicio oral y veredicto",subtitulo:"El debate, la decisión y la pena",etapa:"Juicio oral y debate",color:"amarillo",icono:"🏛️",temas:[{articuloId:"cppba-342",relacionados:["cppba-338"],lecciones:[o({id:"u7-a342-l1",titulo:"Oralidad y publicidad",minutos:3,intro:{titulo:"El corazón del proceso",parrafos:["El debate es oral y público, bajo sanción de nulidad. La prueba se produce frente a los jueces, que escuchan directamente a testigos y peritos (inmediación), y las partes pueden contradecirla.","La publicidad permite el control ciudadano. Pero el tribunal puede resolver que el debate sea total o parcialmente a puertas cerradas cuando la publicidad pudiere afectar el normal desarrollo del juicio, la moral, la intimidad de la víctima o de un testigo, o por razones de seguridad. En caso de duda, siempre se está por la publicidad, y la prensa no puede ser excluida fuera de esos supuestos."],enLaPractica:"En un juicio con una víctima menor de edad, el Tribunal en lo Criminal puede cerrar la sala sólo durante su declaración y reabrirla después."},foco:"El debate será oral y público, bajo sanción de nulidad",preguntas:[e("¿Cómo debe ser el debate según el art. 342?",["Oral y público, bajo sanción de nulidad","Oral y público, salvo que el imputado pida reserva","Oral, y público sólo si lo autoriza la víctima","Público, con lectura de las declaraciones de la IPP"],"Oralidad y publicidad son la regla del juicio; las excepciones son las del propio art. 342, resueltas por el tribunal."),a("El tribunal puede ordenar que una parte del debate se haga a puertas cerradas para proteger la intimidad de una víctima.",!0,"Verdadero: la intimidad de la víctima o de un testigo es una de las causales del art. 342."),a("En caso de duda, debe estarse por la publicidad del debate.",!0,"Verdadero: lo dice expresamente el art. 342."),i("Completá.","Desaparecido el motivo de la resolución, se permitirá el acceso del ___.",["público","imputado","jurado","particular damnificado"],"La clausura dura sólo lo necesario.")]}),o({id:"u7-a342-l2",titulo:"Del ofrecimiento de prueba a los alegatos",minutos:4,intro:{titulo:"El recorrido del juicio común",parrafos:["Recibida la causa e integrado el tribunal, las partes tienen diez días para recusar, ofrecer prueba y decir si quieren una audiencia preliminar (art. 338). Si alguna la pide (y siempre en el juicio por jurados), allí se depura la prueba, se discuten las nulidades y la validez constitucional de los actos de la IPP no resueltas antes, y pueden acordarse estipulaciones probatorias.","Luego viene el debate: apertura, declaración del imputado (si quiere), recepción de la prueba (primero la de la acusación, art. 357), alegatos finales y última palabra del imputado, que se le pregunta bajo sanción de nulidad (art. 368).","Si en el debate surge un hecho nuevo que integra el delito, el Fiscal puede ampliar la acusación, pero respetando el derecho de defensa (principio de congruencia)."]},preguntas:[r("Ordená las etapas del juicio común:",["Ofrecimiento de prueba","Audiencia preliminar","Recepción de la prueba en el debate","Alegatos finales","Última palabra del imputado"],"Después de la última palabra, los jueces pasan a deliberar el veredicto."),e("En el debate aparece un hecho que no estaba en la acusación. ¿Puede el tribunal condenar por él directamente?",["No: el Fiscal debe ampliar la acusación y la defensa debe poder ejercer su derecho","Sí, si el hecho surge claramente de la prueba","Sí, si el particular damnificado lo incluye en su alegato","Sí, si la calificación no cambia"],"Principio de congruencia: no se condena por hechos que no fueron objeto de acusación y defensa."),a("En la audiencia preliminar pueden discutirse nulidades y la validez de los actos de la IPP que se usarán en el debate.",!0,"Verdadero, siempre que esas cuestiones no se hayan planteado y resuelto en la IPP (art. 338 inc. 2)."),e("Si el juicio es por jurados, la audiencia preliminar del art. 338 es…",["Obligatoria","Facultativa, sólo a pedido de parte","Reemplazada por la audiencia del art. 168 bis","Prohibida, para no contaminar al jurado"],"Art. 338: «Cuando el juicio sea por jurados, esta audiencia será obligatoria». En el juicio técnico se hace si una parte la pide."),a("Las partes pueden acordar estipulaciones probatorias sobre hechos en los que no haya controversia sustantiva.",!0,"Verdadero (art. 338 inc. 6). El juez las autoriza si no implican renuncia de derechos constitucionales.")]})]},{articuloId:"cppba-358",relacionados:["cppba-360","cppba-368"],lecciones:[o({id:"u7-a358-l1",titulo:"El imputado en el debate (art. 358)",minutos:4,intro:{titulo:"Declarar es un derecho… y quien declara puede ser preguntado",parrafos:["Durante el debate el imputado puede declarar todas las veces que quiera, siempre que se refiera a su defensa. Puede hablar con su defensor sin que se suspenda la audiencia, pero no mientras declara ni antes de responder una pregunta.","La Ley 15.004 (2017) reformó el último párrafo: si el imputado decide hablar, queda sometido al interrogatorio de su abogado defensor y de las partes contrarias. Antes, el texto sólo mencionaba a las partes contrarias.","Así, el defensor puede guiar la declaración con preguntas, como hace con sus testigos (art. 360). Pero declarar sigue siendo voluntario: el imputado puede callar y su silencio no lo perjudica."],enLaPractica:"En un juicio en Morón, la defensa ofrece que el imputado declare y lo interroga primero para ordenar su relato; después pueden preguntarle el Fiscal y el particular damnificado."},foco:"Al hacer uso de la palabra, el imputado queda sometido al interrogatorio de su abogado defensor y de las partes contrarias.",preguntas:[e("Según el art. 358 vigente, cuando el imputado declara en el debate, ¿quiénes pueden interrogarlo?",["Su abogado defensor y las partes contrarias","Sólo las partes contrarias","Sólo el Presidente del tribunal","Nadie: su declaración no admite preguntas"],"La Ley 15.004 agregó al defensor: «queda sometido al interrogatorio de su abogado defensor y de las partes contrarias»."),a("El imputado puede consultar a su defensor mientras está respondiendo una pregunta del Fiscal.",!1,"Falso. Puede hablar con su defensor durante la audiencia, pero no durante su declaración ni antes de responder preguntas; en esos momentos nadie puede sugerirle nada."),e("El defensor quiere que el imputado declare para explicar por qué estaba en el lugar del hecho. ¿Cómo se organiza según la reforma?",["El defensor puede interrogarlo y luego preguntan las partes contrarias","El imputado debe hacer un relato libre, sin preguntas de su defensor","Debe declarar bajo juramento, como un testigo","Sólo puede leer una declaración escrita por su defensor"],"El imputado nunca jura (art. 310) y no pueden leerse memoriales; pero desde la Ley 15.004 su propio defensor puede interrogarlo."),a("Si el imputado se niega a declarar en el debate, ese silencio puede usarse como indicio en su contra.",!1,"Falso. Declarar es un derecho, no un deber (art. 18 CN y art. 310 CPPBA). En el juicio por jurados, el juez debe explicarles el alcance constitucional de la negativa a declarar (art. 371 ter)."),i("Completá el art. 368.","En último término, el Presidente preguntará a la persona imputada, bajo sanción de ___, si tiene algo que manifestar.",["nulidad","caducidad","inadmisibilidad","preclusión"],"La «última palabra» del imputado es una garantía: omitirla anula el debate.")]})]},{articuloId:"cppba-371",falloClave:{tribunal:"Corte Suprema de Justicia de la Nación",caso:"«Tarifeño» (1989) y «Mostaccio» (2004)",resumen:"En ambos casos el Fiscal, al alegar, pidió la absolución, y aun así el tribunal condenó. La Corte dejó sin efecto las condenas.",regla:"Si el acusador público no mantiene la acusación en el alegato final (y no hay otro acusador que la sostenga), el tribunal no puede condenar: se violarían las formas sustanciales del juicio (acusación, defensa, prueba y sentencia).",nota:"Síntesis didáctica (Mostaccio: Fallos 327:120, 17/2/2004). Hubo matices («Marcilese», 2002), pero «Mostaccio» retomó la doctrina «Tarifeño».",enlaces:[n.mostaccio],ambito:"nacional"},fallosRelacionados:[{tribunal:"Tribunal de Casación Penal de la Provincia de Buenos Aires (Sala IV)",caso:"«Guerendiain» (causa 76.889)",anio:"2016",resumen:"En un juicio por jurados en San Martín, el jurado quedó estancado (9 votos por la culpabilidad). El juez, sin preguntar antes al Fiscal si iba a continuar con la acusación, entregó un nuevo formulario y el jurado volvió a deliberar hasta condenar. La Casación anuló el veredicto y la sentencia y ordenó un nuevo juicio.",regla:"Ante un jurado estancado (art. 371 quater, ap. 2), preguntarle al Fiscal si mantiene la acusación no es una facultad del juez sino un deber que deriva del sistema acusatorio: sin acusación vigente no puede volver a deliberarse ni condenarse.",nota:"Síntesis de la sentencia del 27/9/2016.",enlaces:[n.tcpGuerendiain],ambito:"bonaerense"}],lecciones:[o({id:"u7-a371-l1",titulo:"Las cinco cuestiones del veredicto",minutos:4,intro:{titulo:"Un orden lógico para decidir",parrafos:["Terminado el debate, el tribunal delibera en sesión secreta (su quebrantamiento es causal de nulidad) y vota las cuestiones esenciales: 1) existencia del hecho en su exteriorización; 2) participación de los procesados; 3) eximentes; 4) atenuantes; 5) agravantes.","Cada cuestión depende de la anterior: si se resuelve negativamente la primera o la segunda, o afirmativamente la tercera, no se tratan las demás. Eximentes, atenuantes y agravantes se plantean si fueron discutidas; de oficio, sólo las que favorecen al imputado.","La resolución debe exponer en forma clara, lógica y completa los hechos probados, la valoración de la prueba y por qué se descartan las pruebas decisivas contrarias.","Si el veredicto es absolutorio, se ordena la libertad del imputado y el cese de las restricciones."],enLaPractica:"Las sentencias de los Tribunales en lo Criminal bonaerenses se estructuran siguiendo estas cuestiones: «Primera cuestión: ¿Está probada la existencia del hecho…?»"},foco:"El Tribunal procederá a plantear y votar las cuestiones esenciales referidas a",preguntas:[r("Ordená las cuestiones del veredicto (art. 371):",["Existencia del hecho","Participación del procesado","Existencia de eximentes","Verificación de atenuantes","Concurrencia de agravantes"],"Del hecho a la persona y, recién después, a las circunstancias que modifican la responsabilidad."),e("Si el tribunal concluye que el hecho no existió, ¿qué pasa con las demás cuestiones?",["No se tratan: corresponde la absolución","Se votan igual, para dejar constancia","Se tratan sólo las eximentes","Se suspende la deliberación hasta nueva prueba"],"El orden es lógico y escalonado: resuelta negativamente la primera cuestión, no se tratan las demás."),e("Al deliberar, el tribunal advierte una agravante que nadie discutió en el debate. ¿Puede plantearla?",["No: de oficio sólo puede introducir cuestiones a favor del imputado","Sí, si surge con claridad de la prueba","Sí, si después le corre vista al Fiscal","Sí, siempre que no supere la pena pedida"],"Art. 371: esas cuestiones se plantean si fueron discutidas o si el tribunal las encuentra pertinentes, «en este último caso siempre que fueran en favor del imputado»."),a("Si el tribunal resuelve que hubo una eximente (tercera cuestión), no trata atenuantes ni agravantes.",!0,"Verdadero: el art. 371 dispone que, resuelta afirmativamente la tercera cuestión, no se tratan las demás.")]}),o({id:"u7-a371-l2",titulo:"Acusación, veredicto y jurados",minutos:5,intro:{titulo:"Sin acusación no hay condena",parrafos:["El veredicto puede ser absolutorio o condenatorio. Si es condenatorio, se dicta luego la sentencia con la pena (a veces en una audiencia separada: la cesura del juicio).","Según la doctrina «Tarifeño»/«Mostaccio», si el Fiscal pide la absolución en el alegato y no hay otro acusador, el tribunal no puede condenar.","Desde la Ley 14.543, los delitos con pena máxima superior a 15 años se juzgan, como regla, por jurados. El veredicto de culpabilidad exige al menos 10 votos de 12 (unanimidad si corresponde pena perpetua). Si el jurado queda estancado, el juez debe preguntarle al Fiscal si continúa con la acusación (art. 371 quater)."]},preguntas:[e("En el alegato, el Fiscal pide la absolución y no hay particular damnificado. ¿Puede el tribunal condenar?",["No: sin acusación sostenida no puede condenar","Sí, si la prueba es contundente","Sí, pero sólo con la pena mínima","Sí, si el Fiscal General revoca el pedido"],"Sin acusación sostenida no se cumplen las formas sustanciales del juicio."),i("Completá.","La división del juicio en dos tramos —culpabilidad y pena— se llama ___.",["cesura","deliberación","veredicto","reenvío"],"La cesura permite discutir la pena en una audiencia propia."),a("En la Provincia de Buenos Aires, un homicidio agravado con pena perpetua se juzga, como regla, por jurados.",!0,"Verdadero: la pena máxima supera los 15 años, umbral del art. 22 bis (Ley 14.543). El imputado puede renunciar al jurado en el plazo del art. 336."),e("¿Cuántos votos exige un veredicto de culpabilidad del jurado (art. 371 quater)?",["Al menos 10 de 12; unanimidad si corresponde pena perpetua","Mayoría simple: 7 de 12","Unanimidad en todos los casos","Al menos 8 de 12"],"Diez votos como mínimo; si el delito tiene prevista prisión o reclusión perpetua, unanimidad. Con más de 8 votos pero menos de los exigidos, el jurado se declara estancado."),e("El jurado se declara estancado. ¿Qué debe hacer el juez antes de que vuelva a deliberar?",["Preguntarle al Fiscal si continuará con la acusación","Entregar un nuevo formulario y ordenar otra votación","Disolver el jurado y condenar con el voto mayoritario","Absolver de inmediato al acusado"],"Es un deber, no una facultad (TCP, «Guerendiain», 2016). Si el Fiscal no sigue, se absuelve (salvo que el particular damnificado sostenga la acusación); si sigue, el jurado vuelve a deliberar.")]})]},{articuloId:"cp-41",relacionados:["cp-40"],lecciones:[o({id:"u7-cp41-l1",titulo:"Cómo se gradúa la pena (CP)",minutos:4,intro:{titulo:"Dentro de la escala, ¿cuánto?",parrafos:["Cuando la pena es divisible (por ejemplo, 5 a 15 años), el tribunal fija el monto según atenuantes y agravantes (art. 40 CP), siguiendo las pautas del art. 41 CP.","El art. 41 mira el hecho (naturaleza de la acción, medios, daño y peligro causados) y la persona (edad, educación, conducta precedente, motivos —especialmente la miseria—, participación, reincidencias, vínculos y circunstancias de tiempo, lugar, modo y ocasión).","Y exige que el juez tome conocimiento directo y de visu del imputado y la víctima."],enLaPractica:"En la audiencia de cesura, la defensa acredita trabajo, estudios y contención familiar como atenuantes; el Fiscal, la extensión del daño como agravante."},foco:"especialmente la miseria o la dificultad de ganarse el sustento propio necesario y el de los suyos",preguntas:[e("¿Qué circunstancia menciona expresamente el art. 41 CP al valorar los motivos del delito?",["La miseria o la dificultad de ganarse el sustento propio y de los suyos","El arrepentimiento expresado en la última palabra","La reparación del daño antes del juicio","La duración del proceso hasta la sentencia"],"El inc. 2 del art. 41 destaca «especialmente la miseria o la dificultad de ganarse el sustento». Las otras pueden alegarse dentro de las pautas generales, pero no están nombradas así en la norma."),a("Que el imputado haya ejercido su derecho a no declarar puede valorarse como agravante.",!1,"Falso. El ejercicio de un derecho constitucional no puede agravar la pena."),i("Completá el art. 41 CP.","El juez deberá tomar conocimiento directo y ___ del sujeto, de la víctima y de las circunstancias del hecho.",["de visu","por informes","mediante peritos","por las constancias de la causa"],"El conocimiento «de visu» exige contacto directo del juez con las personas.")]})]}],caso:{id:"caso-u7",titulo:"El debate",rol:"Juez/a del Tribunal en lo Criminal",sede:"Tribunal en lo Criminal · Departamento Judicial Morón (caso ficticio)",hechos:["Se juzga a Nahuel (23) por robo con arma blanca (art. 166 inc. 2 CP: 5 a 15 años). Como el máximo no supera los 15 años, lo juzga un tribunal técnico.","La víctima tiene 16 años. Vos integrás el tribunal."],etapas:[{id:"e1",momento:"Apertura del debate",situacion:"Un canal de noticias pide filmar todo el juicio. La víctima, por medio de su madre, pide declarar sin público.",pregunta:"¿Qué resolvés?",opciones:[{texto:"El debate es público, pero dispongo puertas cerradas durante la declaración de la víctima para proteger su intimidad (art. 342), por resolución fundada.",puntaje:2,devolucion:"Equilibrio correcto entre publicidad y protección de la víctima menor de edad."},{texto:"Todo el juicio a puertas cerradas, para evitar a la prensa.",puntaje:1,devolucion:"La clausura debe limitarse a lo necesario; cerrar todo el juicio excede el fundamento."},{texto:"Juicio totalmente público y filmado, incluida la víctima.",puntaje:0,devolucion:"Ignora la intimidad de una víctima menor, causal expresa de restricción."}],normas:["Art. 342 CPPBA"]},{id:"e2",momento:"Durante la prueba",situacion:"Un testigo dice que Nahuel además amenazó a otra persona esa noche, hecho que no figura en la acusación.",pregunta:"¿Puede incluirse en la condena?",opciones:[{texto:"Sólo si el Fiscal amplía la acusación conforme al código y la defensa puede ejercer su derecho sobre ese hecho.",puntaje:2,devolucion:"Correcto: principio de congruencia y derecho de defensa."},{texto:"Sí, el tribunal puede agregarlo de oficio.",puntaje:0,devolucion:"El tribunal no acusa: eso rompería la imparcialidad y la congruencia."},{texto:"Sí, si el testigo es creíble.",puntaje:0,devolucion:"La credibilidad del testigo no sustituye la acusación formal."}],normas:["Art. 359 CPPBA (ampliación de la acusación)","Art. 18 CN"]},{id:"e2b",momento:"Declaración del imputado",situacion:"La defensa anuncia que, si Nahuel decide declarar, quiere interrogarlo ella primero. El Fiscal se opone: sostiene que el imputado sólo puede hacer un relato libre y responder preguntas de la parte contraria.",pregunta:"¿Cómo resolvés?",opciones:[{texto:"Autorizo: desde la Ley 15.004, al declarar el imputado queda sometido al interrogatorio de su abogado defensor y de las partes contrarias (art. 358).",puntaje:2,devolucion:"Correcto. Es la reforma del último párrafo del art. 358. Declarar sigue siendo voluntario."},{texto:"Rechazo: el defensor no puede preguntarle a su propio defendido.",puntaje:0,devolucion:"Ese era el texto anterior a la reforma. Hoy el art. 358 incluye expresamente al defensor."},{texto:"Autorizo, pero bajo juramento de decir verdad, como cualquier testigo.",puntaje:0,devolucion:"El imputado nunca declara bajo juramento (art. 310): sería obligarlo a autoincriminarse."}],normas:["Art. 358 CPPBA (Ley 15.004)","Art. 310 CPPBA"]},{id:"e3",momento:"Deliberación",situacion:"Ya en sesión secreta, tus colegas quieren empezar discutiendo la pena.",pregunta:"¿Qué cuestión se trata primero?",opciones:[{texto:"La existencia del hecho en su exteriorización (art. 371).",puntaje:2,devolucion:"Exacto. Después la participación, eximentes, atenuantes y agravantes."},{texto:"La pena, para ganar tiempo.",puntaje:0,devolucion:"La pena presupone hecho y participación probados."},{texto:"Los agravantes.",puntaje:0,devolucion:"Los agravantes son la última cuestión."}],normas:["Art. 371 CPPBA"]},{id:"e4",momento:"Cesura: la pena",situacion:"Hay veredicto condenatorio. Nahuel no tiene antecedentes, trabaja desde los 15 años y mantiene a su hermana. Finalmente decidió no declarar en el juicio.",pregunta:"¿Cómo valorás esos datos?",opciones:[{texto:"La falta de antecedentes y su situación laboral y familiar son atenuantes (art. 41 CP); su silencio no puede valorarse en su contra.",puntaje:2,devolucion:"Muy bien: pautas del art. 41 y respeto por el derecho a no declarar."},{texto:"El silencio demuestra falta de arrepentimiento: agravante.",puntaje:0,devolucion:"El ejercicio de un derecho no puede agravar la pena."},{texto:"Impongo el máximo porque los robos son frecuentes.",puntaje:0,devolucion:"La pena se individualiza según el hecho y la persona, no según estadísticas generales."}],normas:["Arts. 40 y 41 CP","Art. 18 CN"]}],cierre:{titulo:"Juzgar con método",texto:"Aplicaste publicidad con límites, congruencia, el orden lógico del veredicto y las pautas de individualización de la pena. Así se construye una sentencia que resiste el control en casación."}}},h={id:"u8",numero:8,titulo:"Abreviado, probation y casación",subtitulo:"Salidas alternativas y revisión de la sentencia",etapa:"Procedimientos especiales y recursos",color:"rojo",icono:"🚀",temas:[{articuloId:"cppba-395",relacionados:["cppba-396","cppba-398","cppba-399"],fallosRelacionados:[{tribunal:"Tribunal de Casación Penal de la Provincia de Buenos Aires (Sala V)",caso:"«Agüero» (causa 133.216)",anio:"2024",resumen:"Un Tribunal en lo Criminal de Florencio Varela condenó en juicio abreviado por tenencia de estupefacientes con fines de comercialización y robo con arma de fuego. La Casación recordó que la sentencia del abreviado no es una mera homologación del acuerdo: el imputado renuncia al debate y a interrogar a los testigos, pero no a una sentencia fundada. Anuló parcialmente la condena por falta de fundamentos sobre la autoría del robo y reenvió para un nuevo pronunciamiento.",regla:"En el juicio abreviado bonaerense el imputado no admite los hechos: el juez debe explicar con las evidencias reunidas por qué tiene por probados el hecho y la autoría, y esa sentencia puede revisarse en casación (art. 401).",nota:"Síntesis de la sentencia del 24/9/2024.",enlaces:[n.tcpAguero],ambito:"bonaerense"}],lecciones:[o({id:"u8-a395-l1",titulo:"Juicio abreviado: cuándo procede",minutos:4,intro:{titulo:"Un acuerdo que evita el debate",parrafos:["Si el Fiscal estima suficiente una pena privativa de libertad no mayor de 15 años (o una pena no privativa, aun conjunta), puede proponer el juicio abreviado. El imputado y su defensor también pueden pedirlo.","Hace falta acuerdo de los tres: Fiscal, imputado y defensor. El Fiscal pide pena y el imputado y su defensor prestan conformidad con ella y con la calificación (art. 396).","La víctima, aunque no sea particular damnificado, es convocada a dar su opinión y el juez la tiene en cuenta (Ley 15.232). El acuerdo puede hacerse hasta 30 días antes de la audiencia de debate (art. 397)."],enLaPractica:"En los departamentos judiciales bonaerenses, una gran parte de las condenas se dicta por juicio abreviado. Por eso es clave que la defensa explique al imputado qué está firmando."},foco:"no mayor de quince (15) años",preguntas:[i("Completá el art. 395.","Procede si el Fiscal estima suficiente una pena privativa de la libertad no mayor de ___.",["quince (15) años","ocho (8) años","diez (10) años","seis (6) años"],"El tope vigente es de 15 años (Ley 13.943); en la redacción original eran 8."),e("¿Quiénes deben estar de acuerdo para el juicio abreviado?",["El Fiscal, el imputado y su defensor","El Fiscal, el imputado, el defensor y la víctima","El imputado y su defensor, con homologación del Juez de Garantías","El Fiscal y el defensor, aunque el imputado no participe"],"Sin el acuerdo de los tres, no hay abreviado. La víctima es convocada a opinar y el juez considera lo que diga, pero no integra el acuerdo."),a("Sólo el Fiscal puede proponer el juicio abreviado.",!1,"Falso. El imputado y su defensor también pueden solicitarlo."),a("La víctima debe ser convocada a opinar sobre el acuerdo aunque no se haya constituido como particular damnificado.",!0,"Verdadero (art. 396, Ley 15.232). Si no quiere concurrir, se le notifica la decisión.")]}),o({id:"u8-a395-l2",titulo:"Límites del abreviado",minutos:4,intro:{titulo:"El techo es la pena acordada",parrafos:["Formalizado el acuerdo, el juez toma contacto de visu con el imputado y le explica las consecuencias. Sólo puede desestimarlo si la voluntad del imputado estaba viciada o si hay una discrepancia insalvable con la calificación (resolución inimpugnable); si no, lo admite (art. 398).","Si lo admite, dicta sentencia en cinco días, fundada en las evidencias recibidas antes del acuerdo. Puede absolver, pero no puede imponer una pena superior a la pedida, ni empeorar el modo de ejecución acordado, ni agregar reglas no convenidas (art. 399).","Si el acuerdo se desestima, nada de lo que admitió el imputado puede usarse en su contra. Contra la sentencia procede casación (criminal) o apelación (correccional), art. 401."]},preguntas:[e("El Fiscal pidió 3 años y el imputado prestó conformidad. ¿Puede el tribunal imponer 4?",["No: no puede superar la pena solicitada por el Fiscal","Sí, si la calificación acordada era errónea","Sí, si la víctima se opuso al acuerdo","Sólo si el imputado es reincidente"],"Art. 399: «No se podrá imponer una pena superior a la pena solicitada por el Agente Fiscal»."),a("En un juicio abreviado el tribunal puede absolver.",!0,"Verdadero: el art. 399 lo prevé expresamente («se podrá absolver al imputado cuando así correspondiere»)."),r("Ordená el trámite del abreviado:",["Acuerdo de Fiscal, imputado y defensor sobre pena y calificación","El juez toma contacto de visu con el imputado","El juez admite el acuerdo (o lo desestima en los casos del art. 398)","Sentencia en cinco días, sin superar la pena pedida por el Fiscal"],"Es el trámite de los arts. 396 a 399."),e("¿Cuándo puede el juez desestimar el acuerdo de juicio abreviado?",["Si la voluntad del imputado estaba viciada o hay discrepancia insalvable con la calificación","Si considera que la pena acordada es demasiado baja","Si la víctima se opone en la audiencia","Si prefiere escuchar a los testigos en un debate"],"El art. 398 (Ley 13.943) limita la desestimación a esos dos supuestos, y esa resolución es inimpugnable."),a("Como hubo acuerdo, la sentencia del juicio abreviado no necesita explicar por qué se tiene por probada la autoría.",!1,"Falso. No es una mera homologación: debe fundarse en las evidencias reunidas y puede anularse por falta de fundamentos (TCP, Sala V, «Agüero», 2024)."),a("Si el tribunal desestima el juicio abreviado, las admisiones del imputado pueden usarse en su contra en el juicio común.",!1,"Falso. El art. 398 dispone que ninguna conformidad o admisión podrá tomarse en su contra como reconocimiento de culpabilidad.")]})]},{articuloId:"cp-76-bis",relacionados:["cp-76-ter","cp-27-bis"],falloClave:{tribunal:"Corte Suprema de Justicia de la Nación",caso:"«Acosta» (2008) y «Góngora» (2013)",resumen:"En «Acosta», la Corte adoptó la tesis amplia: la probation no se limita a delitos con máximo de 3 años, sino que alcanza también a aquellos en los que podría aplicarse condena condicional (art. 76 bis, 4.º párrafo). En «Góngora», sostuvo que en casos de violencia contra la mujer no procede la suspensión del juicio a prueba, por el compromiso internacional de juzgarlos (Convención de Belém do Pará).",regla:"Tesis amplia: procede si cabe una condena en suspenso. Excepción relevante: delitos de violencia de género («Góngora»).",nota:"Síntesis didáctica (Fallos 331:858, 23/4/2008, y 336:392, 23/4/2013).",enlaces:[n.acosta,n.gongora],ambito:"nacional"},lecciones:[o({id:"u8-cp76-l1",titulo:"Suspensión del juicio a prueba",minutos:4,intro:{titulo:"Probation: cumplir reglas en lugar de ir a juicio",parrafos:["El art. 76 bis CP permite al imputado de un delito de acción pública pedir la suspensión del juicio a prueba si la pena máxima no excede de 3 años (también en concurso).","Además, el 4.º párrafo la habilita cuando las circunstancias permitirían dejar en suspenso la condena, con consentimiento del Fiscal. Es la base de la «tesis amplia» (fallo «Acosta»).","El imputado ofrece reparar el daño en la medida de lo posible (sin que eso implique confesión). Si cumple las reglas de conducta durante 1 a 3 años, se extingue la acción penal."],enLaPractica:"En un robo simple (1 mes a 6 años) de un imputado sin antecedentes, la defensa pide la probation por el 4.º párrafo: el mínimo permite una condena en suspenso."},foco:"cuyo máximo no exceda de tres años",preguntas:[e("Robo simple (1 mes a 6 años), imputado sin antecedentes. ¿Puede pedir la probation?",["Sí, por el 4.º párrafo del art. 76 bis (tesis amplia), si cabe condena en suspenso y el Fiscal consiente","No: el máximo supera los 3 años (tesis restrictiva)","Sí, aunque el Fiscal se oponga","Sí, pero sólo si reconoce el hecho"],"La tesis amplia («Acosta») permite la probation cuando sería posible una condena condicional."),a("Ofrecer reparar el daño implica confesar el delito.",!1,"Falso: el art. 76 bis CP aclara que el ofrecimiento no implica confesión ni reconocimiento de responsabilidad civil."),i("Completá el art. 76 ter CP.","El tiempo de la suspensión será fijado por el Tribunal entre ___, según la gravedad del delito.",["uno y tres años","seis meses y un año","cinco y diez años","dos y cuatro años"],"Entre uno y tres años (dos a cuatro es el plazo de las reglas de la condena condicional, art. 27 bis).")]}),o({id:"u8-cp76-l2",titulo:"Cuándo NO procede la probation",minutos:3,intro:{titulo:"Exclusiones legales y jurisprudenciales",parrafos:["El art. 76 bis CP excluye la probation cuando un funcionario público participó en el delito en ejercicio de sus funciones, respecto de delitos reprimidos con inhabilitación y de los ilícitos del Código Aduanero (Ley 22.415) y del Régimen Penal Tributario (Ley 24.769).","La jurisprudencia de la CSJN («Góngora») agregó que no procede en casos de violencia contra la mujer.","Si el imputado cumple, se extingue la acción; si comete un delito o incumple reglas, se hace el juicio. Y si el juicio se hace por un nuevo delito, la pena que se imponga no podrá dejarse en suspenso (art. 76 ter)."]},preguntas:[e("¿En cuál de estos casos NO procede la probation según el art. 76 bis CP?",["Un funcionario público que participó del delito en ejercicio de sus funciones","Un hurto cometido junto con un coimputado mayor de edad","Unas lesiones leves en las que la víctima rechaza la reparación ofrecida","Un concurso real de delitos con máximo de 3 años"],"Es una exclusión expresa del art. 76 bis CP."),a("Según «Góngora», la probation no procede en casos de violencia contra la mujer.",!0,"Verdadero: la Corte lo fundó en la Convención de Belém do Pará."),e("¿Qué pasa si el imputado cumple todas las condiciones durante el plazo fijado?",["Se extingue la acción penal","Se lo condena con pena en suspenso","Se archiva la causa, que puede reabrirse por 3 años","Se lo sobresee, pero queda registrado como antecedente condenatorio"],"Es el efecto previsto en el art. 76 ter CP (y una causal de extinción del art. 59 inc. 7)."),a("Los delitos del Régimen Penal Tributario (Ley 24.769) admiten la suspensión del juicio a prueba.",!1,"Falso: el último párrafo del art. 76 bis los excluye, igual que a los del Código Aduanero (Ley 22.415)."),a("Si se revoca la probation porque el imputado cometió un nuevo delito, la pena que se le imponga podrá dejarse en suspenso.",!1,"Falso. El art. 76 ter dispone que en ese caso la pena no podrá ser dejada en suspenso.")]})]},{articuloId:"cppba-448",falloClave:{tribunal:"Corte Suprema de Justicia de la Nación",caso:"«Casal, Matías Eugenio»",anio:"2005",resumen:"Se discutía si casación sólo podía revisar «cuestiones de derecho» o también los hechos y la prueba. La Corte sostuvo que el recurso de casación debe garantizar el derecho al recurso del art. 8.2.h de la CADH.",regla:"Teoría del «máximo de rendimiento»: el tribunal de casación debe revisar todo lo que pueda revisar, incluidos hechos y prueba, salvo lo que dependa exclusivamente de la inmediación del juicio.",nota:"Síntesis didáctica (Fallos 328:3399, 20/9/2005). El Tribunal de Casación bonaerense aplica esta revisión amplia.",enlaces:[n.casal],ambito:"nacional"},lecciones:[o({id:"u8-a448-l1",titulo:"Motivos de casación",minutos:4,intro:{titulo:"La revisión de la sentencia",parrafos:["El recurso de casación procede contra sentencias definitivas y ciertos autos que ponen fin a la acción o a la pena (art. 450), y lo resuelve el Tribunal de Casación Penal.","Motivos del art. 448: 1) inobservancia o errónea aplicación de un precepto legal o de la doctrina jurisprudencial (si es un defecto del procedimiento, hay que haber reclamado su subsanación o hecho protesta de recurrir); 2) nuevos hechos o elementos de prueba que evidencien que el hecho no existió o que el imputado no lo cometió.","Plazo (art. 451): escrito fundado dentro de 20 días de notificada la resolución, manifestando la intención de recurrir dentro de los primeros 7 días. El trámite no puede exceder seis meses desde el sorteo de la Sala (prorrogables por otros seis en casos complejos), y lo resuelven dos jueces.","En el juicio por jurados, la defensa recurre la condena también por los motivos del art. 448 bis (por ejemplo, instrucciones que condicionaron al jurado o un veredicto que se aparta manifiestamente de la prueba); el Fiscal no puede recurrir (art. 452)."],enLaPractica:"Si un Tribunal en lo Criminal aplicó la agravante de arma (art. 166 inc. 2 CP) a un objeto que no lo era, la defensa recurre en casación por errónea aplicación de un precepto legal."},foco:"Inobservancia o errónea aplicación de un precepto legal o de la doctrina jurisprudencial",preguntas:[e("¿Ante qué tribunal se resuelve el recurso de casación en la Provincia?",["Tribunal de Casación Penal","Cámara de Apelación y Garantías","Suprema Corte de Justicia provincial","Tribunal en lo Criminal en pleno"],"El Tribunal de Casación Penal bonaerense es el órgano de casación."),i("Completá el art. 451.","La presentación del recurso de casación deberá ser efectuada dentro del plazo de ___ de notificada la resolución judicial.",["veinte (20) días","siete (7) días","diez (10) días","quince (15) días"],"Veinte días, bajo sanción de inadmisibilidad."),e("El tribunal calificó como robo un hecho sin violencia ni fuerza. ¿Qué motivo de casación corresponde?",["Inobservancia o errónea aplicación de un precepto legal (art. 448 inc. 1)","Nuevos hechos o elementos de prueba (art. 448 inc. 2)","Apartamiento manifiesto de la prueba (art. 448 bis inc. d)","Apelación ante la Cámara de Garantías"],"Encuadrar mal el hecho en el Código Penal es una errónea aplicación de un precepto legal."),a("Quien quiere recurrir en casación debe manifestar su intención de hacerlo dentro de los primeros 7 días del plazo.",!0,"Verdadero: según el art. 451, si no lo manifiesta, la resolución se reputa firme y consentida a su respecto."),e("Un jurado declaró culpable al imputado. ¿Puede la defensa recurrir?",["Sí, en casación, también por los motivos especiales del art. 448 bis","No: el veredicto del jurado es irrecurrible","Sólo ante la Suprema Corte provincial","Sólo si el veredicto no fue unánime"],"El veredicto es irrecurrible, pero la sentencia condenatoria derivada de él se recurre en casación (arts. 371 quater ap. 7, 448 bis y 454)."),a("En el juicio por jurados, el Fiscal puede recurrir en casación la sentencia absolutoria.",!1,"Falso: «En el procedimiento de juicio por jurados, el Ministerio Público Fiscal carece de legitimación para recurrir» (art. 452).")]}),o({id:"u8-a448-l2",titulo:"Revisión amplia: «Casal»",minutos:3,intro:{titulo:"Casación también mira hechos y prueba",parrafos:["Tradicionalmente se decía que casación sólo controlaba el derecho. Desde «Casal» (2005), el recurso debe permitir una revisión integral de la condena: hechos, prueba y derecho.","El único límite es lo que depende de la inmediación (por ejemplo, la impresión directa que causó un testigo en la sala), aunque incluso eso debe estar razonablemente explicado en la sentencia."]},preguntas:[a("Según «Casal», el tribunal de casación puede revisar la valoración de la prueba.",!0,"Verdadero: es la teoría del máximo de rendimiento."),e("¿Qué norma internacional fundamenta el derecho al recurso amplio?",["El art. 8.2.h de la Convención Americana","El art. 8.1 de la Convención Americana","El art. 7.5 de la Convención Americana","El art. 18 de la Constitución Nacional"],"El art. 8.2.h CADH (y el 14.5 del PIDCP) garantiza el derecho de recurrir el fallo ante un juez o tribunal superior. El 8.1 consagra el plazo razonable y el juez imparcial; el 7.5, el plazo de la prisión preventiva."),r("Ordená la vía recursiva típica contra una condena en la Provincia:",["Sentencia del Tribunal en lo Criminal","Recurso de casación ante el Tribunal de Casación Penal","Recursos extraordinarios ante la Suprema Corte (SCBA)","Recurso extraordinario federal ante la CSJN"],"De la instancia de juicio a la Corte Suprema nacional, pasando por Casación y la SCBA.")]})]}],caso:{id:"caso-u8",titulo:"Tres caminos",rol:"Defensa oficial",sede:"Departamento Judicial Quilmes (caso ficticio)",hechos:["Volvemos con Lucas (19), imputado de robo simple (art. 164 CP) por arrebatar un celular con un empujón. No tiene antecedentes, estudia y trabaja.","La víctima recuperó el teléfono, pero tuvo gastos médicos menores."],etapas:[{id:"e1",momento:"Antes del juicio",situacion:"Analizás las salidas alternativas.",pregunta:"¿Qué pedís primero?",opciones:[{texto:"Suspensión del juicio a prueba por el 4.º párrafo del art. 76 bis CP (tesis amplia, «Acosta»), ofreciendo reparar los gastos médicos.",puntaje:2,devolucion:"Excelente: el mínimo del robo simple permite una condena en suspenso, y Lucas no tiene antecedentes."},{texto:"Nada: la probation sólo procede si el máximo es de 3 años.",puntaje:0,devolucion:"Esa es la tesis restrictiva, superada por la CSJN en «Acosta»."},{texto:"Ir directo a juicio oral.",puntaje:1,devolucion:"Es posible, pero dejarías pasar una salida que evita la condena y extingue la acción."}],normas:["Art. 76 bis CP","Art. 404 CPPBA"]},{id:"e2",momento:"Respuesta del Fiscal",situacion:"El Fiscal se opone con una fórmula genérica: «por razones de política criminal».",pregunta:"¿Cómo respondés?",opciones:[{texto:"Planteo que la oposición fiscal debe ser fundada en las circunstancias del caso; una negativa genérica es arbitraria y el juez debe controlar su razonabilidad.",puntaje:2,devolucion:"Bien. El consentimiento fiscal exigido por el 4.º párrafo no puede ejercerse en forma inmotivada (art. 56: requerimientos motivados)."},{texto:"Acepto: el Fiscal no tiene que explicar nada.",puntaje:0,devolucion:"El Fiscal debe formular sus requerimientos en forma motivada."},{texto:"Pido que decida la víctima.",puntaje:0,devolucion:"La víctima puede aceptar o no la reparación, pero no decide la procedencia de la probation."}],normas:["Art. 76 bis CP","Art. 56 CPPBA"]},{id:"e3",momento:"Plan B: abreviado",situacion:"La probation es rechazada. El Fiscal ofrece un juicio abreviado: 2 años de prisión en suspenso.",pregunta:"¿Qué le explicás a Lucas?",opciones:[{texto:"Que el acuerdo implica renunciar al debate y aceptar el hecho y la calificación; que el tribunal no puede superar la pena pactada y que puede rechazar el acuerdo o incluso absolver.",puntaje:2,devolucion:"Explicación completa: la conformidad debe ser libre e informada."},{texto:"Que firme rápido porque «es un trámite».",puntaje:0,devolucion:"El abreviado termina en una condena: Lucas debe entender lo que acepta."},{texto:"Que el tribunal podría ponerle más pena si quiere.",puntaje:0,devolucion:"Falso: la pena acordada es el techo."}],normas:["Arts. 395 y ss. CPPBA"]},{id:"e4",momento:"Otro final posible",situacion:"Supongamos que Lucas no aceptó, fue a juicio y lo condenaron a 4 años como autor de robo con arma, aunque nunca hubo un arma.",pregunta:"¿Qué recurso interponés?",opciones:[{texto:"Recurso de casación ante el Tribunal de Casación Penal por errónea aplicación de un precepto legal (art. 166 en lugar de 164), en 20 días y manifestando la intención de recurrir en los primeros 7.",puntaje:2,devolucion:"Correcto: el error de calificación es una errónea aplicación de un precepto legal (art. 448 inc. 1); plazos del art. 451."},{texto:"Apelación ante la Cámara de Garantías.",puntaje:0,devolucion:"La Cámara de Garantías revisa resoluciones de la IPP, no sentencias de juicio."},{texto:"Recurso directo ante la Corte Suprema de la Nación.",puntaje:0,devolucion:"Hay que agotar antes las instancias provinciales (Casación y SCBA)."}],normas:["Art. 448 CPPBA","Arts. 164 y 166 CP"]}],cierre:{titulo:"Estrategia completa",texto:"Recorriste las tres grandes salidas: probation (CP), juicio abreviado (CPPBA) y casación. Combinar el código de fondo con el procesal es lo que define una buena estrategia de defensa en la Provincia."}}};export{p as U,r as a,m as b,i as c,b as d,v as e,g as f,f as g,y as h,h as i,o as l,e as o,a as v};
